async function loadScenarios() {
  await loadVisualOperatorCatalog();
  await loadOperatorLibraries({ render: false });
  await loadDraftList({ render: false });
  await loadPublicationList({ render: false });
  await loadVisualAssetOverview({ render: false });
  await loadGoldenCases({ render: false });
  await loadGoldenCertificationStatus({ render: false });
  await loadRunHistory({ render: false });
  const response = await fetch('/api/gateway/examples/scenarios');
  state.customContextText = pretty(DEFAULT_COMPOSER_CONTEXT);
  syncGraphInputSchemaTextFromBuilder({ render: false });
  syncComposerFromBuilder({ render: false });
  state.scenarios = [COMPOSER_SCENARIO, ...await response.json()];
  renderScenarioButtons();
  await selectScenario(COMPOSER_GRAPH);
}

async function loadVisualOperatorCatalog(options = {}) {
  const requestId = ++visualOperatorCatalogRequestSeq;
  const isLatestRequest = () => requestId === visualOperatorCatalogRequestSeq;
  try {
    resetDynamicOperatorTypes();
    const catalogOptions = {
      ...operatorPaletteCatalogQueryOptions(),
      includeDeprecated: Boolean(options.includeDeprecated)
    };
    const fitSource = operatorPaletteFitSourceEndpoint();
    const response = fitSource
      ? await fetchOperatorFitCatalog(fitSource, catalogOptions)
      : await fetch(operatorCatalogUrl(state.builder, catalogOptions));
    if (!response.ok) {
      return;
    }
    const payload = await response.json();
    if (!isLatestRequest()) {
      return;
    }
    const operators = Array.isArray(payload.operators) ? payload.operators : [];
    const diagnostics = normalizeDiagnostics(payload.diagnostics);
    const operatorFitCandidatesByRef = operatorFitCandidateMap(payload.fitCandidates);
    const runtimeBindingProjectionsByRef = operatorProjectionMap(
      payload.runtimeBindingProjections,
      normalizeOperatorRuntimeBindingProjection
    );
    const executablePromotionProjectionsByRef = operatorProjectionMap(
      payload.executablePromotionProjections,
      normalizeOperatorExecutablePromotionProjection
    );
    state.visualOperators = operators;
    state.visualOperatorCatalogWindow = normalizeOperatorCatalogWindow(payload, operators);
    state.visualOperatorCatalogFacets = normalizeOperatorCatalogFacets(payload.facets, operators);
    state.visualOperatorFitCatalog = fitSource ? normalizeOperatorFitCatalog(payload, fitSource) : null;
    state.operatorRuntimeBindingProjectionsByRef = runtimeBindingProjectionsByRef;
    state.operatorExecutablePromotionProjectionsByRef = executablePromotionProjectionsByRef;
    if (diagnostics.length) {
      setVisualCheck(
        'Catalog loaded with diagnostics.',
        visualCheckLevel(diagnostics, true),
        diagnostics
      );
    }
    const activeOperatorRefs = new Set();
    for (const operator of operators) {
      const operatorRef = rememberCatalogOperator(operator, {
        runtimeBindingProjection: runtimeBindingProjectionsByRef[operator?.operatorRef || ''] || null,
        executablePromotionProjection: executablePromotionProjectionsByRef[operator?.operatorRef || ''] || null,
        operatorFitCandidate: operatorFitCandidatesByRef[operator?.operatorRef || ''] || null
      });
      if (operatorRef) {
        activeOperatorRefs.add(operatorRef);
      }
    }
    const nodeOnlyRefs = operatorRefsRequiredByBuilder()
      .filter((operatorRef) => !activeOperatorRefs.has(operatorRef));
    if (nodeOnlyRefs.length) {
      await Promise.all(nodeOnlyRefs.map((operatorRef) => loadVisualOperatorDefinition(operatorRef, {
        paletteVisible: false,
        render: false,
        silent: true
      })));
      if (!isLatestRequest()) {
        return;
      }
    }
    await loadVisualAssetOverview();
    if (!isLatestRequest()) {
      return;
    }
    if (options.render !== false) {
      renderOperatorPalette();
    }
  } catch (error) {
    state.visualOperatorCatalogWindow = null;
    state.visualOperatorFitCatalog = null;
    console.debug('Visual operator catalog unavailable', error);
  }
}

async function loadVisualAssetOverview(options = {}) {
  try {
    const response = await fetch(visualAssetOverviewUrl());
    if (!response.ok) {
      throw new Error(`Asset overview failed with ${response.status}`);
    }
    state.visualAssetOverview = await response.json();
    state.visualAssetOverviewMessage = null;
  } catch (error) {
    state.visualAssetOverview = null;
    state.visualAssetOverviewMessage = { text: error.message, level: 'error' };
  }
  if (options.loadRuntimeBindings !== false) {
    await loadVisualRuntimeBindingRequirements({ render: false });
    await loadVisualRuntimeBindingImplementations({ render: false });
    await loadVisualRuntimeEvidenceChains({ render: false });
  }
  if (options.render !== false) {
    renderVisualAssetOverview();
  }
  return state.visualAssetOverview;
}

async function loadVisualRuntimeBindingRequirements(options = {}) {
  try {
    const response = await fetch(visualRuntimeBindingRequirementsUrl());
    if (!response.ok) {
      throw new Error(`Runtime binding requirements failed with ${response.status}`);
    }
    state.visualRuntimeBindingRequirements = await response.json();
    state.visualRuntimeBindingRequirementsMessage = null;
  } catch (error) {
    state.visualRuntimeBindingRequirements = null;
    state.visualRuntimeBindingRequirementsMessage = { text: error.message, level: 'error' };
  }
  if (options.render !== false) {
    renderVisualAssetOverview();
  }
  return state.visualRuntimeBindingRequirements;
}

async function loadVisualRuntimeBindingImplementations(options = {}) {
  try {
    const response = await fetch(visualRuntimeBindingImplementationsUrl());
    if (!response.ok) {
      throw new Error(`Runtime binding implementations failed with ${response.status}`);
    }
    state.visualRuntimeBindingImplementations = await response.json();
    state.visualRuntimeBindingImplementationsMessage = null;
  } catch (error) {
    state.visualRuntimeBindingImplementations = [];
    state.visualRuntimeBindingImplementationsMessage = { text: error.message, level: 'error' };
  }
  if (options.render !== false) {
    renderVisualAssetOverview();
  }
  return state.visualRuntimeBindingImplementations;
}

async function loadVisualRuntimeEvidenceChains(options = {}) {
  try {
    const response = await fetch(visualRuntimeEvidenceWindowUrl());
    if (!response.ok) {
      throw new Error(`runtime evidence window failed with ${response.status}`);
    }
    const payload = await response.json();
    state.visualRuntimeEvidenceWindow = payload;
    state.visualRuntimeEvidenceImplementationBindings = Array.isArray(payload?.implementationBindings)
      ? payload.implementationBindings
      : [];
    state.visualRuntimeAdapterActivations = Array.isArray(payload?.adapterActivations)
      ? payload.adapterActivations
      : [];
    state.visualRuntimeRolloutObservations = Array.isArray(payload?.rolloutObservations)
      ? payload.rolloutObservations
      : [];
    state.visualExecutableLoweringIntegrations = Array.isArray(payload?.executableLoweringIntegrations)
      ? payload.executableLoweringIntegrations
      : [];
    state.visualRuntimeEvidenceMessage = null;
  } catch (error) {
    state.visualRuntimeEvidenceWindow = null;
    state.visualRuntimeEvidenceImplementationBindings = [];
    state.visualRuntimeAdapterActivations = [];
    state.visualRuntimeRolloutObservations = [];
    state.visualExecutableLoweringIntegrations = [];
    state.visualRuntimeEvidenceMessage = { text: `Runtime evidence chain incomplete: ${error.message}`, level: 'error' };
  }
  if (options.render !== false) {
    renderVisualAssetOverview();
  }
  return visualRuntimeEvidenceRows(
    state.visualRuntimeEvidenceImplementationBindings,
    state.visualRuntimeAdapterActivations,
    state.visualRuntimeRolloutObservations,
    state.visualExecutableLoweringIntegrations
  );
}

function rememberCatalogOperator(operator, options = {}) {
  const operatorRef = operator.operatorRef || '';
  if (!operatorRef || operatorRef === 'httpResource' || operatorRef === 'bloge:decisionTable' || operatorRef === 'bloge:transform') {
    rememberCoreOperatorFingerprint(operatorRef, operator.fingerprint || '');
    return operatorRef;
  }
  const diagnostics = normalizeDiagnostics(operator.diagnostics);
  const runtimeBindingProjection = normalizeOperatorRuntimeBindingProjection(
    options.runtimeBindingProjection || (state.operatorRuntimeBindingProjectionsByRef || {})[operatorRef]
  );
  const executablePromotionProjection = normalizeOperatorExecutablePromotionProjection(
    options.executablePromotionProjection || (state.operatorExecutablePromotionProjectionsByRef || {})[operatorRef]
  );
  rememberOperatorProjections(operatorRef, runtimeBindingProjection, executablePromotionProjection);
  if (!operatorRef.startsWith('resource:')) {
    const inputPorts = normalizeOperatorPorts(operator.ports?.inputs, 'inputs');
    const outputPorts = normalizeOperatorPorts(operator.ports?.outputs, 'output');
    const primaryInput = inputPorts[0] || { name: 'inputs', schema: null };
    const primaryOutput = outputPorts[0] || { name: 'output', schema: null };
    OPERATOR_TYPES[operatorRef] = {
      label: operator.display?.name || readableName(operatorRef),
      kind: 'custom',
      operatorRef,
      visualOperatorRef: operatorRef,
      fingerprint: operator.fingerprint || '',
      inputPort: primaryInput.name,
      outputPort: primaryOutput.name,
      baseId: baseIdForResource(operatorRef),
      inputPorts,
      outputPorts,
      inputSchema: primaryInput.schema,
      outputSchema: primaryOutput.schema,
      configSchema: operator.configSchema,
      description: operator.display?.description || '',
      tags: Array.isArray(operator.display?.tags) ? operator.display.tags.map(String) : [],
      sourceKind: operator.source?.kind || '',
      operatorLibraryId: operator.source?.libraryId || '',
      policy: operator.policy,
      lowering: operator.lowering,
      diagnostics,
      operatorFitCandidate: normalizeOperatorFitCandidate(options.operatorFitCandidate),
      runtimeReadiness: normalizeOperatorRuntimeReadiness(operator.runtimeReadiness),
      runtimeBindingProjection,
      executablePromotionProjection,
      paletteVisible: options.paletteVisible !== false,
      deprecated: Boolean(options.deprecated)
    };
    return operatorRef;
  }
  const resourceId = operator.source?.resourceId
    || operator.lowering?.parameters?.resourceId
    || operatorRef.slice('resource:'.length);
  const inputPorts = normalizeOperatorPorts(operator.ports?.inputs, 'params');
  const outputPorts = normalizeOperatorPorts(operator.ports?.outputs, 'payload');
  const primaryInput = inputPorts[0] || { name: 'params', schema: null };
  const primaryOutput = outputPorts[0] || { name: 'payload', schema: null };
  OPERATOR_TYPES[operatorRef] = {
    label: operator.display?.name || readableName(resourceId),
    kind: 'resource',
    operatorRef: 'httpResource',
    visualOperatorRef: operatorRef,
    fingerprint: operator.fingerprint || '',
    inputPort: primaryInput.name,
    outputPort: primaryOutput.name,
    baseId: baseIdForResource(resourceId),
    resourceId,
    inputPorts,
    outputPorts,
    inputSchema: primaryInput.schema,
    outputSchema: primaryOutput.schema,
    configSchema: operator.configSchema,
    description: operator.display?.description || '',
    tags: Array.isArray(operator.display?.tags) ? operator.display.tags.map(String) : [],
    sourceKind: operator.source?.kind || '',
    operatorLibraryId: operator.source?.libraryId || '',
    policy: operator.policy,
    lowering: operator.lowering,
    diagnostics,
    operatorFitCandidate: normalizeOperatorFitCandidate(options.operatorFitCandidate),
    runtimeReadiness: normalizeOperatorRuntimeReadiness(operator.runtimeReadiness),
    runtimeBindingProjection,
    executablePromotionProjection,
    paletteVisible: options.paletteVisible !== false,
    deprecated: Boolean(options.deprecated)
  };
  return operatorRef;
}

function operatorRefsRequiredByBuilder(builder = state.builder) {
  const refs = new Set();
  for (const node of builder?.nodes || []) {
    if (node.type === 'customOperator' && node.paletteType) {
      refs.add(node.paletteType);
    }
    if (node.type === 'httpResource' && node.resourceId) {
      refs.add(node.paletteType?.startsWith('resource:')
        ? node.paletteType
        : `resource:${node.resourceId}`);
    }
  }
  return [...refs];
}

function operatorPaletteCatalogQueryOptions() {
  return {
    search: state.paletteSearch,
    tags: state.paletteTag ? [state.paletteTag] : [],
    sourceKinds: state.paletteSourceKind ? [state.paletteSourceKind] : [],
    operatorLibraryIds: state.paletteOperatorLibraryId ? [state.paletteOperatorLibraryId] : [],
    loweringModes: state.paletteLoweringMode ? [state.paletteLoweringMode] : [],
    capabilities: state.paletteCapability ? [state.paletteCapability] : [],
    runtimeReadinessStates: state.paletteReadiness ? [state.paletteReadiness] : [],
    itemLimit: state.paletteLimit,
    offset: state.paletteOffset
  };
}

function operatorPaletteFitSourceEndpoint() {
  if (!state.paletteFitSelectedOutput) {
    return null;
  }
  return operatorPaletteSelectedOutputEndpoint();
}

function operatorPaletteSelectedOutputEndpoint() {
  const node = selectedBuilderNode();
  if (!node) {
    return null;
  }
  const source = sourceHandlesForNode(node)
    .find((handle) => canonicalEdgeKind(handle.kind || 'data') === 'data');
  if (!source) {
    return null;
  }
  return {
    nodeId: source.nodeId || node.id,
    port: source.port || '',
    path: source.path || ''
  };
}

function operatorPaletteFitSourceKey(source) {
  if (!source) {
    return '';
  }
  return [source.nodeId || '', source.port || '', source.path || '']
    .map((item) => String(item || '').trim())
    .join(':');
}

function operatorPaletteFitSourceLabel(source) {
  if (!source) {
    return '';
  }
  return endpointLabel(source);
}

async function fetchOperatorFitCatalog(source, options = {}) {
  const scope = builderScope(state.builder);
  const filter = {
    search: options.search || '',
    tags: options.tags || [],
    resourceOnly: Boolean(options.resourceOnly),
    includeDeprecated: Boolean(options.includeDeprecated),
    tenantId: scope.tenantId,
    namespace: scope.namespace,
    environment: scope.environment,
    sourceKinds: options.sourceKinds || [],
    operatorLibraryIds: options.operatorLibraryIds || (options.operatorLibraryId ? [options.operatorLibraryId] : []),
    loweringModes: options.loweringModes || [],
    capabilities: options.capabilities || [],
    runtimeReadinessStates: options.runtimeReadinessStates || []
  };
  return fetch('/api/visual/operators/fit-candidates', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      draft: builderToVisualDraft(state.builder),
      source,
      filter,
      targetSurface: 'input',
      includeRejected: false,
      limit: Number.isFinite(Number(options.itemLimit ?? options.limit))
        ? Number(options.itemLimit ?? options.limit)
        : state.paletteLimit,
      offset: Number.isFinite(Number(options.offset)) ? Number(options.offset) : 0
    })
  });
}

function operatorCatalogUrl(builder = state.builder, options = {}) {
  const scope = builderScope(builder);
  const params = new URLSearchParams();
  params.set('tenantId', scope.tenantId);
  params.set('namespace', scope.namespace);
  params.set('environment', scope.environment);
  if (options.search) {
    params.set('search', options.search);
  }
  for (const tag of options.tags || []) {
    params.append('tags', tag);
  }
  if (options.includeDeprecated) {
    params.set('includeDeprecated', 'true');
  }
  if (options.resourceOnly) {
    params.set('resourceOnly', 'true');
  }
  for (const sourceKind of options.sourceKinds || []) {
    params.append('sourceKind', sourceKind);
  }
  const operatorLibraryIds = options.operatorLibraryIds || (options.operatorLibraryId ? [options.operatorLibraryId] : []);
  for (const operatorLibraryId of operatorLibraryIds) {
    params.append('operatorLibraryId', operatorLibraryId);
  }
  for (const loweringMode of options.loweringModes || []) {
    params.append('loweringMode', loweringMode);
  }
  for (const capability of options.capabilities || []) {
    params.append('capability', capability);
  }
  for (const readiness of options.runtimeReadinessStates || []) {
    params.append('runtimeReadiness', readiness);
  }
  const itemLimit = Number(options.itemLimit ?? options.limit);
  if (Number.isFinite(itemLimit) && itemLimit >= 0) {
    params.set('itemLimit', String(itemLimit));
  }
  const offset = Number(options.offset);
  if (Number.isFinite(offset) && offset >= 0) {
    params.set('offset', String(offset));
  }
  return `/api/visual/operators?${params.toString()}`;
}

function operatorDefinitionUrl(operatorRef, builder = state.builder, options = {}) {
  const scope = builderScope(builder);
  const params = new URLSearchParams();
  params.set('tenantId', scope.tenantId);
  params.set('namespace', scope.namespace);
  params.set('environment', scope.environment);
  if (options.includeDeprecated) {
    params.set('includeDeprecated', 'true');
  }
  if (options.resourceOnly) {
    params.set('resourceOnly', 'true');
  }
  if (options.operatorLibraryId) {
    params.set('operatorLibraryId', options.operatorLibraryId);
  }
  if (options.includeProjections) {
    params.set('includeProjections', 'true');
  }
  return `/api/visual/operators/${encodeURIComponent(operatorRef)}?${params.toString()}`;
}

function normalizeVisualOperatorDetailPayload(payload) {
  const safePayload = payload && typeof payload === 'object' ? payload : {};
  if (safePayload.operator && typeof safePayload.operator === 'object') {
    return {
      schemaVersion: safePayload.schemaVersion || 'bloge.visualOperatorDetail.v1',
      operator: safePayload.operator,
      runtimeBindingProjection: normalizeOperatorRuntimeBindingProjection(safePayload.runtimeBindingProjection),
      executablePromotionProjection: normalizeOperatorExecutablePromotionProjection(
        safePayload.executablePromotionProjection
      ),
      filter: safePayload.filter || {}
    };
  }
  return {
    schemaVersion: safePayload.schemaVersion || 'bloge.visualOperator.v1',
    operator: safePayload,
    runtimeBindingProjection: normalizeOperatorRuntimeBindingProjection(safePayload.runtimeBindingProjection),
    executablePromotionProjection: normalizeOperatorExecutablePromotionProjection(
      safePayload.executablePromotionProjection
    ),
    filter: {}
  };
}

function normalizeOperatorRuntimeBindingProjection(projection) {
  if (!projection || typeof projection !== 'object') {
    return null;
  }
  const operatorRef = String(projection.operatorRef || '').trim();
  const projectionState = String(projection.projectionState || '').trim().toLowerCase();
  const title = String(projection.title || '').trim();
  const summary = String(projection.summary || '').trim();
  if (!operatorRef && !projectionState && !title && !summary) {
    return null;
  }
  return {
    schemaVersion: projection.schemaVersion || 'bloge.operatorRuntimeBindingProjection.v1',
    operatorRef,
    operatorFingerprint: String(projection.operatorFingerprint || '').trim(),
    runtimeReadinessState: String(projection.runtimeReadinessState || '').trim().toLowerCase(),
    executable: projection.executable === true,
    implementationBindingRequired: projection.implementationBindingRequired === true,
    runtimeActivationRequired: projection.runtimeActivationRequired === true,
    projectionState,
    level: normalizeProjectionLevel(projection.level),
    title,
    summary,
    activeBindingId: String(projection.activeBindingId || '').trim(),
    activeBindingRevision: Number(projection.activeBindingRevision) || 0,
    activeBindingState: String(projection.activeBindingState || '').trim().toLowerCase(),
    implementationAdapterKind: String(projection.implementationAdapterKind || '').trim().toLowerCase(),
    implementationEntrypoint: String(projection.implementationEntrypoint || '').trim(),
    runtimeOwner: String(projection.runtimeOwner || '').trim(),
    boundAt: String(projection.boundAt || '').trim(),
    activeAdapterActivationId: String(projection.activeAdapterActivationId || '').trim(),
    activeAdapterActivationRevision: Number(projection.activeAdapterActivationRevision) || 0,
    adapterActivationState: String(projection.adapterActivationState || '').trim().toLowerCase(),
    adapterHealthState: String(projection.adapterHealthState || '').trim().toLowerCase(),
    runtimeEnvironment: String(projection.runtimeEnvironment || '').trim(),
    activatedAt: String(projection.activatedAt || '').trim(),
    diagnostics: normalizeDiagnostics(projection.diagnostics)
  };
}

function normalizeOperatorExecutablePromotionProjection(projection) {
  if (!projection || typeof projection !== 'object') {
    return null;
  }
  const operatorRef = String(projection.operatorRef || '').trim();
  const promotionState = String(projection.promotionState || '').trim().toLowerCase();
  const title = String(projection.title || '').trim();
  const summary = String(projection.summary || '').trim();
  if (!operatorRef && !promotionState && !title && !summary) {
    return null;
  }
  return {
    schemaVersion: projection.schemaVersion || 'bloge.operatorExecutablePromotionProjection.v1',
    operatorRef,
    operatorFingerprint: String(projection.operatorFingerprint || '').trim(),
    executableNow: projection.executableNow === true,
    promotionReady: projection.promotionReady === true,
    promotionState,
    level: normalizeProjectionLevel(projection.level),
    title,
    summary,
    requiredNextAction: String(projection.requiredNextAction || '').trim().toUpperCase(),
    activeBindingId: String(projection.activeBindingId || '').trim(),
    activeAdapterActivationId: String(projection.activeAdapterActivationId || '').trim(),
    adapterKind: String(projection.adapterKind || '').trim().toLowerCase(),
    entrypoint: String(projection.entrypoint || '').trim(),
    runtimeEnvironment: String(projection.runtimeEnvironment || '').trim(),
    activeExecutableLoweringIntegrationId: String(projection.activeExecutableLoweringIntegrationId || '').trim(),
    activeExecutableLoweringIntegrationRevision: Number(projection.activeExecutableLoweringIntegrationRevision) || 0,
    executableLoweringMode: String(projection.executableLoweringMode || '').trim().toLowerCase(),
    executorKind: String(projection.executorKind || '').trim().toLowerCase(),
    executorEntrypoint: String(projection.executorEntrypoint || '').trim(),
    integratedAt: String(projection.integratedAt || '').trim(),
    observedAt: String(projection.observedAt || '').trim(),
    diagnostics: normalizeDiagnostics(projection.diagnostics)
  };
}

function normalizeProjectionLevel(level) {
  const normalized = String(level || '').trim().toLowerCase();
  return ['success', 'info', 'warning', 'error'].includes(normalized) ? normalized : 'info';
}

function operatorProjectionMap(projections, normalizer) {
  const map = {};
  for (const projection of Array.isArray(projections) ? projections : []) {
    const normalized = normalizer(projection);
    if (normalized?.operatorRef) {
      map[normalized.operatorRef] = normalized;
    }
  }
  return map;
}

function rememberOperatorProjections(operatorRef, runtimeBindingProjection, executablePromotionProjection) {
  const normalizedRef = String(operatorRef || runtimeBindingProjection?.operatorRef
    || executablePromotionProjection?.operatorRef || '').trim();
  if (!normalizedRef) {
    return;
  }
  if (runtimeBindingProjection) {
    state.operatorRuntimeBindingProjectionsByRef = {
      ...(state.operatorRuntimeBindingProjectionsByRef || {}),
      [normalizedRef]: runtimeBindingProjection
    };
  }
  if (executablePromotionProjection) {
    state.operatorExecutablePromotionProjectionsByRef = {
      ...(state.operatorExecutablePromotionProjectionsByRef || {}),
      [normalizedRef]: executablePromotionProjection
    };
  }
}

