async function exportVisualRuntimeBindingHandoffBundle() {
  state.visualRuntimeBindingHandoffBundle = null;
  state.visualRuntimeBindingHandoffReview = null;
  try {
    const response = await fetch(visualRuntimeBindingHandoffBundleUrl());
    const payload = await response.json().catch(() => null);
    if (!response.ok) {
      throw new Error(`Runtime binding handoff export failed with ${response.status}`);
    }
    const displayed = Number(payload?.displayedCount ?? payload?.requirements?.length ?? 0) || 0;
    const total = Number(payload?.total || 0) || 0;
    const operatorContracts = Number(payload?.operatorContracts?.length || 0) || 0;
    const contractSummary = operatorContracts
      ? ` Included ${operatorContracts} operator contract snapshot${operatorContracts === 1 ? '' : 's'}.`
      : ' No operator contract snapshots were available for this window.';
    const hasMore = payload?.hasMore ? ' Current query has more matching requirements after this window.' : '';
    state.visualRuntimeBindingHandoffBundle = payload;
    state.visualRuntimeBindingHandoffReview = null;
    state.visualRuntimeBindingHandoffBundleMessage = {
      text: `Exported ${displayed} of ${total} runtime binding requirement(s).${contractSummary}${hasMore}`,
      level: 'success'
    };
    $('output').textContent = pretty({ status: response.status, runtimeBindingHandoffBundle: payload });
  } catch (error) {
    state.visualRuntimeBindingHandoffBundleMessage = {
      text: error.message,
      level: 'error'
    };
  }
  renderVisualAssetOverview();
}

async function reviewVisualRuntimeBindingHandoffBundle() {
  const bundle = state.visualRuntimeBindingHandoffBundle;
  if (!bundle) {
    state.visualRuntimeBindingHandoffBundleMessage = {
      text: 'Export a runtime binding handoff bundle before reviewing it.',
      level: 'warning'
    };
    renderVisualAssetOverview();
    return;
  }
  try {
    const response = await fetch(visualRuntimeBindingHandoffReviewUrl(), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(bundle)
    });
    const payload = await response.json().catch(() => null);
    if (!response.ok) {
      throw new Error(`Runtime binding handoff review failed with ${response.status}`);
    }
    state.visualRuntimeBindingHandoffReview = payload;
    state.visualRuntimeBindingHandoffBundleMessage = {
      text: visualRuntimeBindingHandoffReviewMessage(payload),
      level: payload?.level || 'info'
    };
    $('output').textContent = pretty({ status: response.status, runtimeBindingHandoffReview: payload });
  } catch (error) {
    state.visualRuntimeBindingHandoffReview = null;
    state.visualRuntimeBindingHandoffBundleMessage = {
      text: error.message,
      level: 'error'
    };
  }
  renderVisualAssetOverview();
}

async function transitionVisualRuntimeBindingImplementation(bindingId, action) {
  const binding = visualRuntimeBindingImplementationById(bindingId);
  if (!binding) {
    state.visualRuntimeBindingImplementationMessage = {
      text: `Runtime binding implementation '${bindingId}' is not in the current list.`,
      level: 'warning'
    };
    renderVisualAssetOverview();
    return null;
  }
  const normalizedAction = String(action || '').trim().toLowerCase();
  const replacement = normalizedAction === 'supersede'
    ? visualRuntimeBindingImplementationSupersedeReplacement(binding)
    : null;
  if (normalizedAction === 'supersede' && !replacement) {
    renderVisualAssetOverview();
    return null;
  }
  const request = visualRuntimeBindingImplementationTransitionRequest(binding, normalizedAction, replacement);
  try {
    const response = await fetch(visualRuntimeBindingImplementationTransitionUrl(binding.bindingId, normalizedAction), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(request)
    });
    const payload = await response.json().catch(() => null);
    const diagnostics = normalizeDiagnostics(payload?.diagnostics);
    const accepted = response.ok && payload?.accepted !== false;
    state.visualRuntimeBindingImplementationMessage = {
      text: visualRuntimeBindingImplementationTransitionMessage(
        normalizedAction,
        binding,
        replacement,
        payload,
        diagnostics,
        response.status
      ),
      level: accepted ? 'success' : visualCheckLevel(diagnostics, false)
    };
    $('output').textContent = pretty({ status: response.status, runtimeBindingImplementationTransition: payload });
  } catch (error) {
    state.visualRuntimeBindingImplementationMessage = {
      text: error.message,
      level: 'error'
    };
  }
  await loadVisualAssetOverview({ render: false });
  renderVisualAssetOverview();
  return state.visualRuntimeBindingImplementationMessage;
}

function visualRuntimeBindingImplementationById(bindingId) {
  const normalized = String(bindingId || '').trim();
  return (Array.isArray(state.visualRuntimeBindingImplementations) ? state.visualRuntimeBindingImplementations : [])
    .find((binding) => binding?.bindingId === normalized) || null;
}

function visualRuntimeBindingImplementationSupersedeReplacement(binding) {
  const candidates = (Array.isArray(state.visualRuntimeBindingImplementations) ? state.visualRuntimeBindingImplementations : [])
    .filter((candidate) => candidate
      && candidate.bindingId !== binding.bindingId
      && candidate.operatorRef === binding.operatorRef
      && ['ready-to-bind', 'requires-review'].includes(String(candidate.state || '').toLowerCase()));
  if (!candidates.length) {
    state.visualRuntimeBindingImplementationMessage = {
      text: `No ready replacement binding is visible for '${binding.bindingId}'.`,
      level: 'warning'
    };
    return null;
  }
  if (candidates.length === 1) {
    return candidates[0];
  }
  const suggested = candidates.map((candidate) => candidate.bindingId).join(', ');
  const selected = window.prompt(`Replacement binding id (${suggested})`, candidates[0].bindingId);
  const normalized = String(selected || '').trim();
  const replacement = candidates.find((candidate) => candidate.bindingId === normalized) || null;
  if (!replacement) {
    state.visualRuntimeBindingImplementationMessage = {
      text: normalized
        ? `Replacement binding '${normalized}' is not a visible ready proposal for '${binding.operatorRef}'.`
        : 'Supersede cancelled.',
      level: normalized ? 'warning' : 'info'
    };
  }
  return replacement;
}

function visualRuntimeBindingImplementationTransitionRequest(binding, action, replacement = null) {
  return {
    schemaVersion: 'bloge.visualRuntimeBindingImplementationTransition.v1',
    actor: 'visual-canvas',
    reason: visualRuntimeBindingImplementationTransitionReason(action, binding, replacement),
    changeSource: 'gateway-browser',
    changeSummary: visualRuntimeBindingImplementationTransitionSummary(action, binding, replacement),
    ackReview: true,
    replacementBindingId: replacement?.bindingId || '',
    expectedRevision: Number(binding?.revision || 0) || 0,
    expectedReplacementRevision: replacement ? (Number(replacement.revision || 0) || 0) : 0
  };
}

function visualRuntimeBindingImplementationTransitionReason(action, binding, replacement = null) {
  const operator = binding?.operatorRef || 'operator';
  if (action === 'unbind') {
    return `User reviewed active runtime implementation '${binding?.bindingId || ''}' for ${operator} before unbinding it in the browser.`;
  }
  if (action === 'supersede') {
    return `User reviewed replacement runtime implementation '${replacement?.bindingId || ''}' for ${operator} before superseding '${binding?.bindingId || ''}' in the browser.`;
  }
  return `User reviewed runtime implementation '${binding?.bindingId || ''}' for ${operator} before binding it in the browser.`;
}

function visualRuntimeBindingImplementationTransitionSummary(action, binding, replacement = null) {
  const revision = Number(binding?.revision || 0) || 0;
  if (action === 'unbind') {
    return `Unbound runtime implementation ${binding?.bindingId || ''}@${revision}.`;
  }
  if (action === 'supersede') {
    return `Superseded runtime implementation ${binding?.bindingId || ''}@${revision} with ${replacement?.bindingId || ''}@${Number(replacement?.revision || 0) || 0}.`;
  }
  return `Bound runtime implementation ${binding?.bindingId || ''}@${revision}.`;
}

function visualRuntimeBindingImplementationTransitionMessage(
  action,
  binding,
  replacement,
  payload,
  diagnostics = [],
  status = 0
) {
  const accepted = payload?.accepted !== false && status >= 200 && status < 300;
  if (!accepted) {
    return diagnosticMessage(
      diagnostics,
      `Runtime binding implementation ${action} rejected with ${status || 'unknown status'}.`
    );
  }
  if (action === 'unbind') {
    return `Runtime binding implementation '${binding.bindingId}' is unbound.`;
  }
  if (action === 'supersede') {
    return `Runtime binding implementation '${replacement?.bindingId || ''}' superseded '${binding.bindingId}'.`;
  }
  return `Runtime binding implementation '${binding.bindingId}' is bound.`;
}

function visualRuntimeBindingHandoffReviewMessage(review) {
  if (!review) {
    return 'Runtime binding handoff review returned no payload.';
  }
  const stateLabel = operatorPaletteFacetLabel(review.state || 'reviewed');
  const matched = Number(review.matchedCount || 0) || 0;
  const drifted = Number(review.driftedCount || 0) || 0;
  const missing = Number(review.missingCount || 0) || 0;
  const fresh = Number(review.newCurrentWindowCount || 0) || 0;
  const contractMatched = Number(review.operatorContractMatchedCount || 0) || 0;
  const contractDrifted = Number(review.operatorContractDriftedCount || 0) || 0;
  const contractMissing = Number(review.operatorContractMissingCount || 0) || 0;
  const contractFresh = Number(review.operatorContractNewCurrentWindowCount || 0) || 0;
  const contractAttention = contractDrifted + contractMissing + contractFresh;
  const contractSummary = contractAttention
    ? ` Contracts: ${contractMatched} current, ${contractDrifted} drifted, ${contractMissing} missing, ${contractFresh} new current-window.`
    : '';
  return `Handoff review ${stateLabel}: ${matched} current, ${drifted} drifted, ${missing} missing, ${fresh} new in current window.${contractSummary}`;
}

function visualBundleFingerprintSuffix(fingerprint) {
  return fingerprint ? ` (${fingerprint})` : '';
}

function visualRuntimeBindingHandoffReviewRows(review) {
  if (!review) {
    return [];
  }
  const rows = [];
  if (review.sourceBundleFingerprint) {
    rows.push({
      level: 'info',
      label: 'Snapshot fingerprint',
      value: review.sourceBundleFingerprint
    });
  }
  const operatorContracts = Number(review.exportedOperatorContractCount || 0) || 0;
  if (operatorContracts) {
    const contractStatus = review.operatorContractStatusCounts || {};
    const contractStatusSummary = visualRuntimeBindingHandoffReviewCountFacetSummary(contractStatus, '', true);
    rows.push({
      level: (Number(review.operatorContractDriftedCount || 0)
        + Number(review.operatorContractMissingCount || 0)
        + Number(review.operatorContractNewCurrentWindowCount || 0)) > 0 ? 'warning' : 'info',
      label: 'Operator contract snapshots',
      value: `${operatorContracts} contract${operatorContracts === 1 ? '' : 's'} exported with this handoff`
        + (contractStatusSummary ? `; ${contractStatusSummary}` : '')
    });
  }
  const routingSummary = visualRuntimeBindingHandoffReviewRoutingSummary(review);
  if (routingSummary) {
    rows.push({
      level: String(review.state || '').toLowerCase() === 'current' ? 'success' : 'info',
      label: 'Runtime binding routing',
      value: routingSummary
    });
  }
  const categorySummary = visualRuntimeBindingHandoffReviewCategorySummary(review.fieldChangeCategoryCounts);
  if (categorySummary) {
    rows.push({
      level: 'warning',
      label: 'Drift categories',
      value: categorySummary
    });
  }
  const contractCategorySummary = visualRuntimeBindingHandoffReviewCategorySummary(
    review.operatorContractFieldChangeCategoryCounts
  );
  if (contractCategorySummary) {
    rows.push({
      level: 'warning',
      label: 'Operator contract drift categories',
      value: contractCategorySummary
    });
  }
  const itemRows = (Array.isArray(review.items) ? review.items : [])
    .filter((item) => item && String(item.status || '').toLowerCase() !== 'current')
    .slice(0, 5)
    .map((item) => ({
      level: ['error', 'warning', 'info', 'success'].includes(String(item.level || '').toLowerCase())
        ? String(item.level).toLowerCase()
        : 'warning',
      label: visualRuntimeBindingHandoffReviewItemLabel(item),
      value: visualRuntimeBindingHandoffReviewItemValue(item)
    }));
  rows.push(...itemRows);
  const contractItemRows = (Array.isArray(review.operatorContractItems) ? review.operatorContractItems : [])
    .filter((item) => item && String(item.status || '').toLowerCase() !== 'current')
    .slice(0, 5)
    .map((item) => ({
      level: ['error', 'warning', 'info', 'success'].includes(String(item.level || '').toLowerCase())
        ? String(item.level).toLowerCase()
        : 'warning',
      label: visualRuntimeBindingHandoffReviewContractItemLabel(item),
      value: visualRuntimeBindingHandoffReviewItemValue(item)
    }));
  rows.push(...contractItemRows);
  const newKeys = Array.isArray(review.newCurrentWindowRequirementKeys)
    ? review.newCurrentWindowRequirementKeys.filter(Boolean)
    : [];
  if (newKeys.length) {
    rows.push({
      level: 'info',
      label: 'New current-window requirements',
      value: newKeys.slice(0, 3).join(', ') + (newKeys.length > 3 ? ` +${newKeys.length - 3} more` : '')
    });
  }
  return rows;
}

function visualRuntimeBindingHandoffReviewRoutingSummary(review) {
  if (!review) {
    return '';
  }
  const segments = [];
  const exported = visualRuntimeBindingHandoffReviewDistributionSummary(review.exportedWindowDistribution);
  const current = visualRuntimeBindingHandoffReviewDistributionSummary(review.currentWindowDistribution);
  const fresh = visualRuntimeBindingHandoffReviewDistributionSummary(review.newCurrentWindowDistribution);
  if (exported) {
    segments.push(`Exported ${exported}`);
  }
  if (current) {
    segments.push(`Current ${current}`);
  }
  if (fresh) {
    segments.push(`New ${fresh}`);
  }
  return segments.join(' | ');
}

function visualRuntimeBindingHandoffReviewDistributionSummary(distribution) {
  const count = Number(distribution?.requirementCount || 0) || 0;
  if (!count) {
    return '';
  }
  const parts = [
    visualRuntimeBindingHandoffReviewCountFacetSummary(distribution?.operatorLibraryIdCounts, 'library', false),
    visualRuntimeBindingHandoffReviewCountFacetSummary(distribution?.handoffLaneCounts, 'lane'),
    visualRuntimeBindingHandoffReviewCountFacetSummary(distribution?.handoffKindCounts, 'work'),
    visualRuntimeBindingHandoffReviewCountFacetSummary(distribution?.handoffTargetCounts, 'target', false)
  ].filter(Boolean);
  return `${count} requirement${count === 1 ? '' : 's'}${parts.length ? ` (${parts.join(', ')})` : ''}`;
}

function visualRuntimeBindingHandoffReviewCountFacetSummary(counts = {}, suffix = '', prettify = true) {
  return Object.entries(counts || {})
    .filter(([, count]) => Number(count || 0) > 0)
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([key, count]) => {
      const label = prettify ? operatorPaletteFacetLabel(key) : key;
      return `${label}${suffix ? ` ${suffix}` : ''}: ${Number(count || 0)}`;
    })
    .join(', ');
}

function visualRuntimeBindingHandoffReviewCategorySummary(counts = {}) {
  return Object.entries(counts || {})
    .filter(([, count]) => Number(count || 0) > 0)
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([category, count]) => `${operatorPaletteFacetLabel(category)} ${Number(count || 0)}`)
    .join(' · ');
}

function visualRuntimeBindingHandoffReviewItemLabel(item) {
  const status = operatorPaletteFacetLabel(item?.status || 'review');
  const requirementKey = item?.requirementKey || item?.exportedRequirement?.requirementKey || '';
  const target = item?.currentRequirement?.targetLabel || item?.exportedRequirement?.targetLabel || requirementKey;
  return [status, target].filter(Boolean).join(' · ');
}

function visualRuntimeBindingHandoffReviewContractItemLabel(item) {
  const status = operatorPaletteFacetLabel(item?.status || 'review');
  const contract = item?.currentContract || item?.exportedContract || {};
  const displayName = contract?.display?.name || contract?.display?.title || '';
  const target = displayName || item?.operatorRef || contract?.operatorRef || '';
  return [status, target].filter(Boolean).join(' · ');
}

function visualRuntimeBindingHandoffReviewItemValue(item) {
  const status = String(item?.status || '').toLowerCase();
  if (status === 'missing') {
    return item?.message || 'Exported requirement is no longer present in the current read model.';
  }
  const changes = Array.isArray(item?.fieldChanges) ? item.fieldChanges : [];
  if (changes.length) {
    return changes.slice(0, 3).map(visualRuntimeBindingFieldChangeText).join(' · ')
      + (changes.length > 3 ? ` · +${changes.length - 3} more field changes` : '');
  }
  const fields = Array.isArray(item?.changedFields) ? item.changedFields.filter(Boolean) : [];
  if (fields.length) {
    return `Changed fields: ${fields.slice(0, 5).join(', ')}${fields.length > 5 ? ', ...' : ''}.`;
  }
  return item?.message || 'Review item requires attention.';
}

function visualRuntimeBindingFieldChangeText(change) {
  const field = change?.field ? visualRuntimeBindingFieldLabel(change.field) : 'Field';
  const category = change?.category ? operatorPaletteFacetLabel(change.category) : '';
  const exportedValue = change?.exportedValue == null || change.exportedValue === '' ? '(empty)' : String(change.exportedValue);
  const currentValue = change?.currentValue == null || change.currentValue === '' ? '(empty)' : String(change.currentValue);
  const prefix = category ? `${category} ${field}` : field;
  return `${prefix}: ${exportedValue} -> ${currentValue}`;
}

function visualRuntimeBindingFieldLabel(value) {
  return String(value || '')
    .trim()
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .replaceAll('-', ' ')
    .replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function visualDraftsUrl(builder = state.builder) {
  return scopedVisualAuthoringUrl('/api/visual/drafts', builder);
}

function visualDraftHistoryUrl(builder = state.builder) {
  return scopedVisualAuthoringUrl('/api/visual/drafts/history', builder);
}

function visualDraftSummariesUrl(builder = state.builder) {
  return scopedVisualAuthoringUrl('/api/visual/drafts/summaries', builder);
}

function visualPublicationSummariesUrl(builder = state.builder) {
  const url = scopedVisualAuthoringUrl('/api/visual/publications/summaries', builder);
  const artifactKind = normalizePublicationArtifactKindFilter(state.publicationArtifactKindFilter || '');
  return artifactKind ? `${url}&artifactKind=${encodeURIComponent(artifactKind)}` : url;
}

function scopedVisualAuthoringUrl(path, builder = state.builder) {
  const scope = builderScope(builder);
  const params = new URLSearchParams();
  params.set('tenantId', scope.tenantId);
  params.set('namespace', scope.namespace);
  params.set('environment', scope.environment);
  return `${path}?${params.toString()}`;
}

function builderScope(builder = state.builder) {
  return {
    tenantId: builder?.tenantId || 'demo-tenant',
    namespace: builder?.namespace || 'local',
    environment: builder?.environment || 'browser'
  };
}

function scopeFromControls() {
  return {
    tenantId: normalizedScopeValue($('scope-tenant')?.value, 'demo-tenant'),
    namespace: normalizedScopeValue($('scope-namespace')?.value, 'local'),
    environment: normalizedScopeValue($('scope-environment')?.value, 'browser')
  };
}

function normalizedScopeValue(value, fallback) {
  const normalized = String(value || '').trim();
  return normalized || fallback;
}

async function applyBuilderScopeFromControls() {
  const next = scopeFromControls();
  const current = builderScope();
  const changed = current.tenantId !== next.tenantId
      || current.namespace !== next.namespace
      || current.environment !== next.environment;
  if (changed) {
    recordBuilderHistory('Change authoring scope');
  }
  state.builder.tenantId = next.tenantId;
  state.builder.namespace = next.namespace;
  state.builder.environment = next.environment;
  if (changed) {
    state.visualCheck = { message: 'Not checked', level: 'info', diagnostics: [] };
  }
  renderScopeStatus('Loading catalog...', 'info');
  await loadVisualOperatorCatalog();
  renderOperatorPalette();
  renderSelectedOperatorEditor();
  renderGraphOutputEditor();
  renderVisualCheck();
  renderScopeStatus();
}

function renderScopeStatus(message = '', level = 'info') {
  const target = $('scope-status');
  if (!target) return;
  const scope = builderScope();
  target.textContent = message || `${scope.tenantId} / ${scope.namespace} / ${scope.environment}`;
  target.className = `scope-status ${level}`;
}

function rememberCoreOperatorFingerprint(operatorRef, fingerprint) {
  if (!fingerprint) {
    return;
  }
  const type = {
    httpResource: 'httpResource',
    'bloge:decisionTable': 'decisionTable',
    'bloge:transform': 'transform'
  }[operatorRef];
  if (type && OPERATOR_TYPES[type]) {
    OPERATOR_TYPES[type].fingerprint = fingerprint;
  }
}

function normalizeOperatorPorts(ports, fallbackName) {
  if (!Array.isArray(ports) || ports.length === 0) {
    return [];
  }
  return ports.map((port) => ({
    name: port?.name || fallbackName,
    schema: port?.schema || null,
    required: Boolean(port?.required),
    description: port?.description || ''
  }));
}

function inputPortsForSpec(spec) {
  if (Array.isArray(spec?.inputPorts)) {
    return spec.inputPorts;
  }
  return [{ name: spec?.inputPort || 'inputs', schema: spec?.inputSchema || null, required: true }];
}

function dslSafeInputPortsForSpec(spec) {
  return inputPortsForSpec(spec).filter((port) =>
    operatorLibraryInputPortDslPathSafe({ ...port, name: port?.name || spec?.inputPort || 'inputs' }));
}

function outputPortsForSpec(spec) {
  if (spec?.lowering?.mode === 'branch') {
    return [];
  }
  if (Array.isArray(spec?.outputPorts)) {
    return spec.outputPorts;
  }
  return [{ name: spec?.outputPort || 'output', schema: spec?.outputSchema || null, required: true }];
}

function dslSafeOutputPortsForSpec(spec) {
  return outputPortsForSpec(spec).filter(outputPortDslPathSafe);
}

function allOutputPortsDslPathSafe(spec) {
  const outputPorts = outputPortsForSpec(spec);
  return outputPorts.length > 0 && outputPorts.every(outputPortDslPathSafe);
}

function inputPortForInputPath(spec, path) {
  const ports = inputPortsForSpec(spec);
  const matches = ports.filter((port) => schemaDeclaresPath(port.schema, path));
  if (matches.length === 1) {
    return matches[0].name;
  }
  return ports[0]?.name || spec?.inputPort || 'inputs';
}

function inputKeyForPortPath(spec, portName, path) {
  if (!path) {
    return portName || spec?.inputPort || 'inputs';
  }
  const matchingPorts = inputPortsForSpec(spec).filter((port) => schemaDeclaresPath(port.schema, path));
  return matchingPorts.length > 1 ? `${portName || spec?.inputPort || 'inputs'}.${path}` : path;
}

function customInputPathForKey(node, key) {
  const paths = node.customInputPaths || {};
  return Object.prototype.hasOwnProperty.call(paths, key) ? paths[key] : key;
}

function customInputPortForKey(node, spec, key) {
  return node.customInputPorts?.[key] || inputPortForInputPath(spec, customInputPathForKey(node, key));
}

function inputUnionBranchForTarget(node, target) {
  const spec = specForNode(node);
  const key = target.key || inputKeyForPortPath(spec, target.port || spec.inputPort || 'inputs', target.path || '');
  if (node.type === 'httpResource') {
    return normalizedUnionBranchSelection(node.paramInputUnionBranches?.[key]);
  }
  if (node.type === 'customOperator') {
    return normalizedUnionBranchSelection(node.customInputUnionBranches?.[key]);
  }
  return null;
}

function inputUnionBranchesForPort(node, spec, portName) {
  const property = node.type === 'httpResource'
    ? 'paramInputUnionBranches'
    : (node.type === 'customOperator' ? 'customInputUnionBranches' : '');
  if (!property) {
    return {};
  }
  const selections = {};
  Object.entries(node[property] || {}).forEach(([key, value]) => {
    const selection = normalizedUnionBranchSelection(value);
    if (!selection) {
      return;
    }
    const path = node.type === 'customOperator' ? customInputPathForKey(node, key) : key;
    const resolvedPort = node.type === 'customOperator' ? customInputPortForKey(node, spec, key) : portName;
    if (!path || (resolvedPort && portName && resolvedPort !== portName)) {
      return;
    }
    selections[path] = selection;
  });
  return selections;
}

function inputUnionBranchesForTarget(node, target) {
  const spec = specForNode(node);
  const path = String(target.path || '');
  const segments = path.split('.').filter(Boolean);
  if (segments.length <= 1) {
    return {};
  }
  const branchSelections = inputUnionBranchesForPort(node, spec, target.port || spec.inputPort || 'inputs');
  const selected = {};
  for (let i = 1; i < segments.length; i += 1) {
    const branchPath = segments.slice(0, i).join('.');
    const selection = normalizedUnionBranchSelection(branchSelections[branchPath]);
    if (selection) {
      selected[branchPath] = selection;
    }
  }
  return selected;
}

function targetWithSelectedUnionBranch(node, target) {
  const selection = inputUnionBranchForTarget(node, target);
  const targetUnionBranches = inputUnionBranchesForTarget(node, target);
  const enriched = selection ? { ...target, targetUnionBranch: selection } : { ...target };
  return Object.keys(targetUnionBranches).length
    ? { ...enriched, targetUnionBranches }
    : enriched;
}

function setInputUnionBranchForTarget(node, target, selection) {
  const key = target.key || target.path || '';
  if (!key) {
    return;
  }
  const normalized = normalizedUnionBranchSelection(selection);
  const property = node.type === 'httpResource'
    ? 'paramInputUnionBranches'
    : (node.type === 'customOperator' ? 'customInputUnionBranches' : '');
  if (!property) {
    return;
  }
  node[property] = node[property] || {};
  if (normalized) {
    node[property][key] = normalized;
  } else {
    delete node[property][key];
    if (!Object.keys(node[property]).length) {
      delete node[property];
    }
  }
}

function configUnionBranchForPath(node, path) {
  return normalizedUnionBranchSelection(node.configUnionBranches?.[String(path || '')]);
}

function setConfigUnionBranchForPath(node, path, selection) {
  const key = String(path || '');
  const normalized = normalizedUnionBranchSelection(selection);
  node.configUnionBranches = node.configUnionBranches || {};
  if (normalized) {
    node.configUnionBranches[key] = normalized;
    return;
  }
  delete node.configUnionBranches[key];
  if (!Object.keys(node.configUnionBranches).length) {
    delete node.configUnionBranches;
  }
}

function outputKeyForPortPath(spec, portName, path) {
  if (!path) {
    return portName || spec?.outputPort || 'output';
  }
  const matchingPorts = outputPortsForSpec(spec).filter((port) => schemaDeclaresPath(port.schema, path));
  return matchingPorts.length > 1 ? `${portName || spec?.outputPort || 'output'}.${path}` : path;
}

function customOutputPathForKey(node, key) {
  const paths = node.customOutputPaths || {};
  return Object.prototype.hasOwnProperty.call(paths, key) ? paths[key] : key;
}

function customOutputPortForKey(node, spec, key) {
  const portName = node.customOutputPorts?.[key];
  if (portName) {
    return portName;
  }
  return outputPortsForSpec(spec)[0]?.name || spec?.outputPort || 'output';
}

function bindingTargetPathForKey(key, binding) {
  if (Object.prototype.hasOwnProperty.call(binding || {}, 'targetPath')) {
    return binding.targetPath || '';
  }
  return binding?.targetPort === key ? '' : key;
}

function schemaForPort(spec, role, portName) {
  const ports = role === 'source' ? outputPortsForSpec(spec) : inputPortsForSpec(spec);
  return ports.find((port) => port.name === portName)?.schema
    || (role === 'source' ? spec?.outputSchema : spec?.inputSchema)
    || null;
}

function resetDynamicOperatorTypes() {
  for (const key of Object.keys(OPERATOR_TYPES)) {
    if (!CORE_OPERATOR_TYPES.has(key)) {
      delete OPERATOR_TYPES[key];
    }
  }
}

function renderScenarioButtons() {
  const target = $('scenarios');
  target.innerHTML = '';
  for (const scenario of state.scenarios) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'scenario-button';
    button.setAttribute('aria-current', state.selected?.graphName === scenario.graphName ? 'true' : 'false');
    button.innerHTML = `<strong>${scenario.title}</strong><span>${scenario.pattern}</span>`;
    button.addEventListener('click', () => selectScenario(scenario.graphName));
    target.appendChild(button);
  }
}

async function selectScenario(graphName) {
  closeStream();
  const scenario = state.scenarios.find((item) => item.graphName === graphName);
  if (!scenario) return;
  state.selected = scenario;
  state.selectedNodeId = null;
  state.lastPayload = null;
  if (isComposerSelected()) {
    state.builder.selectedId = state.builder.selectedId || state.builder.nodes[0]?.id || null;
    state.layout = layoutFromBuilder(state.builder);
    state.selectedNodeId = state.builder.selectedId;
  } else {
    const response = await fetch(scenario.diagramPath);
    state.layout = await response.json();
  }
  renderScenarioButtons();
  renderScenario();
}

function renderScenario() {
  $('scenario-title').textContent = state.selected.title;
  $('scenario-pattern').textContent = state.selected.pattern;
  $('concepts').innerHTML = state.selected.concepts.map((concept) => `<span class="chip">${escapeHtml(concept)}</span>`).join('');
  renderExampleBrief();
  $('inspector').classList.toggle('composer-mode', isComposerSelected());
  renderInputForm();
  renderDecisionTable();
  renderCanvasNavigator();
  renderDiagram();
  renderNodeDetails(state.layout?.nodes?.[0]);
  renderDecisionSummary(null);
  $('output').textContent = pretty({});
}

function renderExampleBrief() {
  const insight = SCENARIO_EXPLANATIONS[state.selected.graphName] || {
    capability: 'BLOGE makes the graph structure, resource calls, policies, and runtime result visible from one executable model.',
    signal: 'Compare the selected graph path, node metadata, and output payload after running the example.'
  };
  $('example-description').textContent = state.selected.description || `${state.selected.title} demonstrates ${state.selected.pattern}.`;
  $('example-capability').textContent = insight.capability;
  $('example-signal').textContent = insight.signal;
}

