async function openVisualAssetAction(index, actionKey = '') {
  const items = state.visualAssetOverview?.actionQueue?.items || [];
  const item = actionKey
    ? items.find((candidate) => candidate?.actionKey === actionKey) || items[Number(index)]
    : items[Number(index)];
  if (!item?.targetId) {
    return null;
  }
  state.activeVisualAssetAction = item;
  const context = visualAssetActionContext(item);
  renderVisualAssetOverview();
  switch (String(item.targetKind || '').toLowerCase()) {
    case 'draft': {
      const draft = await openLibraryImpactDraftTarget(item.targetId, -1);
      if (context) {
        setDraftMessage(`Opened overview action: ${context.message}`, context.level);
      }
      return draft;
    }
    case 'publication': {
      const publication = await openLibraryImpactPublicationTarget(item.targetId, -1);
      if (context) {
        setPublicationMessage(`Opened overview action: ${context.message}`, context.level);
      }
      return publication;
    }
    case 'operator':
      return focusOperatorPaletteRef(item.targetId, context);
    case 'runtime-evidence':
      return openVisualRuntimeEvidenceAction(item, context);
    default:
      return null;
  }
}

async function openVisualRuntimeEvidenceAction(item, context = null) {
  const target = visualRuntimeEvidenceTargetParts(item?.targetId);
  if (!target.id) {
    return null;
  }
  const operatorRef = String(item?.operatorRef || '').trim();
  const operatorLibraryId = String(item?.operatorLibraryId || '').trim();
  if (target.kind === 'binding') {
    state.visualRuntimeBindingImplementationQuery = normalizeVisualRuntimeBindingImplementationQuery({
      operatorRef,
      state: ''
    });
    await loadVisualRuntimeBindingImplementations({ render: false });
    const binding = (Array.isArray(state.visualRuntimeBindingImplementations)
      ? state.visualRuntimeBindingImplementations
      : [])
      .find((candidate) => candidate?.bindingId === target.id) || null;
    state.activeVisualRuntimeBindingImplementation = binding;
    state.visualRuntimeEvidenceQuery = normalizeVisualRuntimeEvidenceQuery({
      evidenceKind: 'implementation-binding',
      operatorRef,
      operatorLibraryId,
      bindingId: target.id,
      activationId: '',
      lifecycleState: '',
      rolloutState: '',
      rolloutSignal: '',
      breachedOnly: false
    });
    await loadVisualRuntimeEvidenceChains({ render: false });
    state.activeVisualRuntimeEvidence = null;
    if (context && binding) {
      state.visualRuntimeBindingImplementationMessage = {
        text: `Opened overview action: ${context.message}`,
        level: context.level
      };
    }
    renderVisualAssetOverview();
    return binding;
  }

  state.visualRuntimeEvidenceQuery = normalizeVisualRuntimeEvidenceQuery({
    evidenceKind: target.kind === 'activation'
      ? 'adapter-activation'
      : (target.kind === 'integration' ? 'executable-lowering-integration' : ''),
    operatorRef,
    operatorLibraryId,
    bindingId: '',
    activationId: target.kind === 'activation' ? target.id : '',
    lifecycleState: '',
    rolloutState: '',
    rolloutSignal: '',
    breachedOnly: false
  });
  await loadVisualRuntimeEvidenceChains({ render: false });
  let row = findVisualRuntimeEvidenceRow(target);
  if (row) {
    const breachedSignals = Array.isArray(row.breachedRolloutSignals)
      ? row.breachedRolloutSignals.filter(Boolean)
      : [];
    const focusedRolloutSignal = row.kind === 'rollout-observation' && breachedSignals.length
      ? breachedSignals[0]
      : '';
    state.visualRuntimeEvidenceQuery = normalizeVisualRuntimeEvidenceQuery({
      evidenceKind: row.kind || '',
      operatorRef: row.operatorRef || operatorRef,
      operatorLibraryId: row.operatorLibraryId || operatorLibraryId,
      bindingId: row.bindingId || '',
      activationId: row.activationId || '',
      lifecycleState: row.kind === 'rollout-observation' ? '' : row.state,
      rolloutState: row.kind === 'rollout-observation' ? row.state : '',
      rolloutSignal: focusedRolloutSignal,
      breachedOnly: Boolean(focusedRolloutSignal)
    });
    await loadVisualRuntimeEvidenceChains({ render: false });
    row = findVisualRuntimeEvidenceRow(target) || row;
  }
  state.activeVisualRuntimeEvidence = row || null;
  if (context && row) {
    state.visualRuntimeEvidenceMessage = {
      text: `Opened overview action: ${context.message}`,
      level: context.level
    };
  }
  renderVisualAssetOverview();
  return row;
}

function visualRuntimeEvidenceTargetParts(targetId = '') {
  const raw = String(targetId || '').trim();
  const separator = raw.indexOf(':');
  if (separator <= 0) {
    return { kind: '', id: raw };
  }
  return {
    kind: raw.slice(0, separator).trim().toLowerCase(),
    id: raw.slice(separator + 1).trim()
  };
}

function findVisualRuntimeEvidenceRow(target) {
  const rows = visualRuntimeEvidenceRows(
    state.visualRuntimeEvidenceImplementationBindings,
    state.visualRuntimeAdapterActivations,
    state.visualRuntimeRolloutObservations,
    state.visualExecutableLoweringIntegrations
  );
  return rows.find((row) =>
    visualRuntimeEvidenceTargetKindMatches(row.kind, target.kind)
      && row.id === target.id)
    || rows.find((row) => row.id === target.id)
    || null;
}

function visualRuntimeEvidenceTargetKindMatches(rowKind, targetKind) {
  const normalizedRowKind = String(rowKind || '').trim().toLowerCase();
  const normalizedTargetKind = String(targetKind || '').trim().toLowerCase();
  return normalizedRowKind === normalizedTargetKind
    || (normalizedTargetKind === 'binding' && normalizedRowKind === 'implementation-binding')
    || (normalizedTargetKind === 'activation' && normalizedRowKind === 'adapter-activation')
    || (normalizedTargetKind === 'rollout' && normalizedRowKind === 'rollout-observation')
    || (normalizedTargetKind === 'integration' && normalizedRowKind === 'executable-lowering-integration');
}

async function openVisualRuntimeBindingRequirement(index, requirementKey = '') {
  const items = state.visualRuntimeBindingRequirements?.items || [];
  const item = requirementKey
    ? items.find((candidate) => candidate?.requirementKey === requirementKey) || items[Number(index)]
    : items[Number(index)];
  if (!item?.targetId) {
    return null;
  }
  state.activeVisualRuntimeBindingRequirement = item;
  const context = visualRuntimeBindingRequirementContext(item);
  renderVisualAssetOverview();
  switch (String(item.targetKind || '').toLowerCase()) {
    case 'draft': {
      const draft = await openLibraryImpactDraftTarget(item.targetId, -1);
      if (context) {
        setDraftMessage(`Opened runtime binding requirement: ${context.message}`, context.level);
      }
      return draft;
    }
    case 'publication': {
      const publication = await openLibraryImpactPublicationTarget(item.targetId, -1);
      if (context) {
        setPublicationMessage(`Opened runtime binding requirement: ${context.message}`, context.level);
      }
      return publication;
    }
    default:
      return null;
  }
}

async function focusOperatorPaletteRef(operatorRef, context = null) {
  const normalized = String(operatorRef || '').trim();
  if (!normalized) {
    return null;
  }
  state.paletteSearch = normalized;
  state.paletteKind = '';
  state.paletteTag = '';
  state.paletteSourceKind = '';
  state.paletteOperatorLibraryId = '';
  state.paletteCapability = '';
  state.paletteReadiness = '';
  state.paletteLoweringMode = '';
  state.paletteOffset = 0;
  state.focusedOperatorRef = normalized;
  await loadVisualOperatorCatalog({ render: true });
  await loadVisualOperatorDefinition(normalized, { render: false });
  renderOperatorPalette();
  const search = $('operator-palette-search');
  if (search) {
    search.focus();
  }
  const detail = $('operator-palette-detail');
  if (detail && typeof detail.scrollIntoView === 'function') {
    detail.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
  }
  setVisualCheck(
    context ? `Opened overview action: ${context.message}` : `Focused operator ${normalized} in the palette.`,
    context?.level || 'info',
    state.visualCheck?.diagnostics || [],
    state.visualCheck?.readiness || null,
    state.visualCheck?.actionReadiness || null
  );
  return normalized;
}

function draftHistoryOptionLabel(entry) {
  const revision = entry.active ? (entry.currentRevision || entry.latestRevision || 0) : (entry.latestRevision || 0);
  const status = entry.active ? 'active' : 'deleted';
  const readiness = draftSummaryReadinessLabel(draftSummaryFor(entry.draftId));
  const readinessText = readiness ? ` · ${readiness}` : '';
  const summary = entry.changeSummary ? ` · ${entry.changeSummary}` : '';
  const reason = entry.reason ? ` · ${entry.reason}` : '';
  return `${entry.graphName || entry.draftId} @${revision} · ${status}${readinessText}${summary}${reason}`;
}

function draftSummaryFor(draftId) {
  return (Array.isArray(state.draftSummaries) ? state.draftSummaries : [])
    .find((summary) => summary?.draftId === draftId) || null;
}

function draftSummaryReadinessState(summary) {
  return normalizeReadinessState(summary?.readiness?.state);
}

function draftSummaryReadinessLabel(summary) {
  const state = draftSummaryReadinessState(summary);
  return state ? operatorPaletteFacetLabel(state) : '';
}

function draftAssetSummary(summaries) {
  const result = {
    total: 0,
    activeCount: 0,
    recoverableDeletedCount: 0,
    validCount: 0,
    invalidCount: 0,
    runtimeExecutableCount: 0,
    designOnlyCount: 0,
    runtimeBlockedCount: 0,
    governanceReviewCount: 0,
    repairRequiredCount: 0,
    unknownReadinessCount: 0
  };
  for (const summary of Array.isArray(summaries) ? summaries : []) {
    result.total += 1;
    if (summary?.active === false) {
      result.recoverableDeletedCount += 1;
    } else {
      result.activeCount += 1;
    }
    if (summary?.valid === false) {
      result.invalidCount += 1;
    } else {
      result.validCount += 1;
    }
    switch (draftSummaryReadinessState(summary)) {
      case 'runtime-executable':
        result.runtimeExecutableCount += 1;
        break;
      case 'design-only':
        result.designOnlyCount += 1;
        break;
      case 'runtime-blocked':
        result.runtimeBlockedCount += 1;
        break;
      case 'governance-review':
        result.governanceReviewCount += 1;
        break;
      case 'draft-repair-required':
      case 'catalog-repair-required':
        result.repairRequiredCount += 1;
        break;
      default:
        result.unknownReadinessCount += 1;
        break;
    }
  }
  return result;
}

function draftAssetSummaryLevel(summary) {
  if (!summary || !summary.total) return 'info';
  if (summary.invalidCount || summary.repairRequiredCount) return 'error';
  if (summary.runtimeBlockedCount || summary.governanceReviewCount) return 'warning';
  if (summary.designOnlyCount || summary.recoverableDeletedCount) return 'info';
  return 'success';
}

function draftAssetInterestingSummaries(summaries) {
  return (Array.isArray(summaries) ? summaries : [])
    .filter(Boolean)
    .filter((summary) => summary?.active === false
      || summary?.valid === false
      || draftSummaryReadinessState(summary) !== 'runtime-executable');
}

function draftAssetSummaryRows(summaries, limit = 5) {
  return draftAssetInterestingSummaries(summaries)
    .map((summary) => {
      const revision = summary.active ? (summary.currentRevision || summary.latestRevision || 0) : (summary.latestRevision || 0);
      const status = summary.active === false ? 'deleted' : 'active';
      const readiness = draftSummaryReadinessLabel(summary);
      const label = [`${summary.graphName || summary.draftId} @${revision}`, status, readiness]
        .filter(Boolean)
        .join(' · ');
      const value = visualGraphReadinessStatusText(summary.readiness)
        || (summary.active === false ? 'Recoverable deleted draft' : 'No readiness snapshot');
      return { label, value, active: summary.active !== false };
    })
    .slice(0, Math.max(0, Number(limit) || 0));
}

function renderDraftAssetSummary() {
  const target = $('draft-asset-summary');
  if (!target) return;
  const summaries = Array.isArray(state.draftSummaries) ? state.draftSummaries : [];
  if (!summaries.length) {
    target.hidden = true;
    target.innerHTML = '';
    return;
  }
  const summary = draftAssetSummary(summaries);
  const interestingCount = draftAssetInterestingSummaries(summaries).length;
  const rows = draftAssetSummaryRows(summaries);
  const overflow = Math.max(0, interestingCount - rows.length);
  const stats = [
    ['Total', summary.total],
    ['Active', summary.activeCount],
    ['Recoverable', summary.recoverableDeletedCount],
    ['Valid', summary.validCount],
    ['Invalid', summary.invalidCount],
    ['Runtime executable', summary.runtimeExecutableCount],
    ['Design only', summary.designOnlyCount],
    ['Runtime blocked', summary.runtimeBlockedCount],
    ['Governance review', summary.governanceReviewCount],
    ['Repair required', summary.repairRequiredCount]
  ].filter(([, value], index) => index < 4 || value)
    .map(([label, value]) => `<span><strong>${escapeHtml(value)}</strong> ${escapeHtml(label)}</span>`)
    .join('');
  target.hidden = false;
  target.className = `library-impact-panel ${escapeHtml(draftAssetSummaryLevel(summary))}`;
  target.innerHTML = `
    <div class="library-impact-head">
      <strong>Draft Asset Index</strong>
      <span>${escapeHtml(`${summary.designOnlyCount} design / ${summary.runtimeExecutableCount} executable`)}</span>
    </div>
    <div class="library-impact-risk-summary">${escapeHtml('Server-derived draft readiness is visible before loading a draft.')}</div>
    <div class="library-impact-stats">${stats}</div>
    ${rows.length ? `<div class="library-impact-risks">${rows.map((row) => `
      <div class="library-impact-risk ${escapeHtml(draftAssetRowLevel(row))}">
        <strong>${escapeHtml(row.label)}</strong>
        <span>${escapeHtml(row.value)}</span>
      </div>
    `).join('')}${overflow ? `<div class="library-impact-more">+${overflow} more non-executable, deleted, or review-required drafts</div>` : ''}</div>` : ''}
  `;
}

function draftAssetRowLevel(row) {
  const text = String(row?.value || '').toLowerCase();
  if (text.includes('repair')) return 'error';
  if (text.includes('blocked') || text.includes('governance')) return 'warning';
  return row?.active === false ? 'warning' : 'info';
}

function renderDraftRevisionControls() {
  const select = $('draft-revision-select');
  if (!select) return;
  const revisions = state.draftRevisions || [];
  const options = revisions.length
    ? revisions.map((draft) => {
      const selected = Number(draft.revision || 0) === Number(state.selectedDraftRevision || 0) ? ' selected' : '';
      return `<option value="${escapeHtml(draft.revision || 0)}"${selected}>${escapeHtml(revisionOptionLabel(draft))}</option>`;
    })
    : [`<option value="">${state.currentDraftId ? 'No history loaded' : 'Select a draft'}</option>`];
  select.innerHTML = options.join('');
  select.disabled = !state.currentDraftId || !revisions.length;
  select.onchange = () => {
    state.selectedDraftRevision = Number(select.value || 0);
    loadDraftRevisionDiff();
  };

  const reloadButton = $('reload-revisions');
  const previewButton = $('preview-revision');
  const restoreButton = $('restore-revision');
  if (reloadButton) {
    reloadButton.disabled = !state.currentDraftId;
    reloadButton.onclick = loadDraftRevisions;
  }
  if (previewButton) {
    previewButton.disabled = !state.currentDraftId || !state.selectedDraftRevision;
    previewButton.onclick = previewSelectedDraftRevision;
  }
  if (restoreButton) {
    restoreButton.disabled = !state.currentDraftId || !state.selectedDraftRevision;
    restoreButton.onclick = restoreSelectedDraftRevision;
  }
  renderDraftRevisionDiff();
}

function revisionOptionLabel(draft) {
  const nodeCount = Array.isArray(draft.nodes) ? draft.nodes.length : 0;
  const metadata = draft.revisionMetadata || {};
  const actor = metadata.updatedBy || metadata.createdBy || 'visual-canvas';
  const summary = metadata.changeSummary || `${nodeCount} nodes`;
  return `@${draft.revision || 0} · ${summary} · ${actor}`;
}

function renderDraftRevisionDiff() {
  const target = $('draft-revision-diff');
  if (!target) return;
  const diff = state.draftRevisionDiff;
  if (!diff || !state.selectedDraftRevision) {
    target.hidden = true;
    target.innerHTML = '';
    return;
  }
  const level = draftRevisionDiffLevel(diff);
  target.hidden = false;
  target.className = `library-impact-panel ${level}`;
  const counts = [
    ['Nodes', `${diff.addedNodeCount || 0}+/${diff.removedNodeCount || 0}-/${diff.changedNodeCount || 0}~`],
    ['Edges', `${diff.addedEdgeCount || 0}+/${diff.removedEdgeCount || 0}-/${diff.changedEdgeCount || 0}~`]
  ].map(([label, value]) => `<span><strong>${escapeHtml(value)}</strong> ${escapeHtml(label)}</span>`).join('');
  const graphChanges = Array.isArray(diff.graphChanges) ? diff.graphChanges : [];
  const nodeChanges = Array.isArray(diff.nodeChanges) ? diff.nodeChanges : [];
  const edgeChanges = Array.isArray(diff.edgeChanges) ? diff.edgeChanges : [];
  const graphRows = graphChanges.slice(0, 4).map((change) => `
    <div class="library-impact-code ${escapeHtml(draftRevisionDiffRiskLevel(change.risk))}">
      <strong>${escapeHtml(change.field || 'graph')}</strong>
      <span>${escapeHtml(change.summary || '')}</span>
    </div>
  `).join('');
  const nodeRows = nodeChanges.slice(0, 5).map((change) => `
    <div class="library-impact-risk">
      <strong>${escapeHtml(change.nodeId || 'node')}</strong>
      <span>${escapeHtml(change.changeKind || 'CHANGED')} · ${escapeHtml(changeRiskLabel(change.risk))}</span>
      <small>${escapeHtml(change.summary || '')}</small>
    </div>
  `).join('');
  const edgeRows = edgeChanges.slice(0, 4).map((change) => `
    <div class="library-impact-risk">
      <strong>${escapeHtml(change.edgeId || 'edge')}</strong>
      <span>${escapeHtml(change.changeKind || 'CHANGED')} · ${escapeHtml(changeRiskLabel(change.risk))}</span>
      <small>${escapeHtml(change.summary || '')}</small>
    </div>
  `).join('');
  const hiddenRows = Math.max(0, nodeChanges.length - 5) + Math.max(0, edgeChanges.length - 4);
  const hiddenText = hiddenRows ? `<div class="library-impact-more">+${hiddenRows} more draft changes</div>` : '';
  target.innerHTML = `
    <div class="library-impact-head">
      <strong>Draft Diff</strong>
      <span>@${escapeHtml(diff.baseRevision || 0)} -> @${escapeHtml(diff.targetRevision || 0)} · ${escapeHtml(changeRiskLabel(diff.changeRisk))}</span>
    </div>
    <div class="library-impact-risk-summary">${escapeHtml(diff.changeSummary || 'No graph draft surface changes.')}</div>
    <div class="library-impact-stats">${counts}</div>
    ${graphRows ? `<div class="library-impact-codes">${graphRows}</div>` : ''}
    ${nodeRows || edgeRows ? `<div class="library-impact-risks">${nodeRows}${edgeRows}${hiddenText}</div>` : ''}
  `;
}

function draftRevisionDiffLevel(diff) {
  if (!diff?.changed) {
    return 'success';
  }
  const risk = String(diff.changeRisk || '').toUpperCase();
  if (risk === 'BREAKING_SCHEMA') {
    return 'error';
  }
  return risk === 'METADATA' ? 'success' : 'warning';
}

function draftRevisionDiffRiskLevel(risk) {
  const normalized = String(risk || '').toUpperCase();
  if (normalized === 'BREAKING_SCHEMA') {
    return 'error';
  }
  return normalized === 'METADATA' ? 'success' : 'warning';
}

function renderDraftDependencyReport() {
  const target = $('draft-dependencies');
  if (!target) return;
  const report = state.draftDependencyReport;
  const message = state.draftDependencyMessage;
  if (!report && !message) {
    target.hidden = true;
    target.innerHTML = '';
    return;
  }
  const level = report ? draftDependencyReportLevel(report) : (message?.level || 'info');
  target.hidden = false;
  target.className = `library-impact-panel ${escapeHtml(level)}`;
  if (!report) {
    target.innerHTML = `
      <div class="library-impact-head">
        <strong>Draft Dependencies</strong>
        <span>${escapeHtml(message?.text || 'Dependency report unavailable.')}</span>
      </div>
    `;
    return;
  }
  const stats = [
    ['Operators', report.operatorDependencyCount || 0],
    ['Nodes', report.nodeCount || 0],
    ['Missing', report.missingOperatorCount || 0],
    ['Scope', report.scopeMismatchOperatorCount || 0],
    ['Drifted', report.driftedFingerprintCount || 0],
    ['Unsnapshotted', report.missingFingerprintCount || 0],
    ['Schema break', report.schemaBreakingDriftCount || 0],
    ['Schema review', report.schemaCompatibleDriftCount || 0]
  ].map(([label, value]) => `<span><strong>${escapeHtml(value)}</strong> ${escapeHtml(label)}</span>`).join('');
  const readinessRows = draftDependencyCountRows(report.runtimeReadinessStateCounts || {}, 'readiness');
  const sourceRows = draftDependencyCountRows(report.sourceKindCounts || {}, 'source');
  const libraryRows = draftDependencyCountRows(report.operatorLibraryIdCounts || {}, 'library');
  const schemaRows = draftDependencyCountRows(report.schemaCompatibilityStateCounts || {}, 'schema');
  const operatorRows = draftDependencyOperatorRows(report);
  const nodeRows = draftDependencyNodeRows(report);
  target.innerHTML = `
    <div class="library-impact-head">
      <strong>Draft Dependencies</strong>
      <span>${escapeHtml(`${report.draftId || 'draft'}@${report.revision || 0}`)}</span>
    </div>
    <div class="library-impact-risk-summary">${escapeHtml(draftDependencySummary(report))}</div>
    <div class="library-impact-stats">${stats}</div>
    ${readinessRows || sourceRows || libraryRows || schemaRows
      ? `<div class="library-impact-codes">${readinessRows}${sourceRows}${libraryRows}${schemaRows}</div>`
      : ''}
    ${operatorRows ? `<div class="library-impact-risks">${operatorRows}</div>` : ''}
    ${nodeRows ? `<div class="library-impact-risks">${nodeRows}</div>` : ''}
  `;
  for (const button of target.querySelectorAll('[data-draft-dependency-node]')) {
    button.addEventListener('click', () => {
      focusCanvasNode(button.dataset.draftDependencyNode);
    });
  }
  for (const button of target.querySelectorAll('[data-draft-dependency-rebase]')) {
    button.addEventListener('click', () => {
      rebaseOperatorFingerprint(button.dataset.draftDependencyRebase);
    });
  }
}

function draftDependencyReportLevel(report) {
  if ((Number(report?.missingOperatorCount) || 0) > 0
      || (Number(report?.scopeMismatchOperatorCount) || 0) > 0
      || (Number(report?.schemaBreakingDriftCount) || 0) > 0) {
    return 'error';
  }
  if ((Number(report?.driftedFingerprintCount) || 0) > 0
      || (Number(report?.missingFingerprintCount) || 0) > 0
      || (Number(report?.schemaCompatibleDriftCount) || 0) > 0) {
    return 'warning';
  }
  const readinessCounts = report?.runtimeReadinessStateCounts || {};
  if (Number(readinessCounts.CATALOG_MISSING || readinessCounts.catalog_missing || 0) > 0
      || Number(readinessCounts.SCOPE_MISMATCH || readinessCounts.scope_mismatch || 0) > 0) {
    return 'error';
  }
  if (Object.keys(readinessCounts).some((key) =>
    ['DESIGN_ONLY', 'RUNTIME_BLOCKED', 'GOVERNANCE_REVIEW', 'CATALOG_REPAIR_REQUIRED']
      .includes(String(key || '').toUpperCase()))) {
    return 'warning';
  }
  return 'success';
}

function draftDependencySummary(report) {
  const parts = [];
  const missing = Number(report?.missingOperatorCount) || 0;
  const scopeMismatch = Number(report?.scopeMismatchOperatorCount) || 0;
  const drifted = Number(report?.driftedFingerprintCount) || 0;
  const unsnapshotted = Number(report?.missingFingerprintCount) || 0;
  const schemaBreaking = Number(report?.schemaBreakingDriftCount) || 0;
  const schemaCompatible = Number(report?.schemaCompatibleDriftCount) || 0;
  if (missing) {
    parts.push(`${missing} catalog-missing node${missing === 1 ? '' : 's'}`);
  }
  if (scopeMismatch) {
    parts.push(`${scopeMismatch} scope-mismatched node${scopeMismatch === 1 ? '' : 's'}`);
  }
  if (drifted) {
    parts.push(`${drifted} drifted fingerprint${drifted === 1 ? '' : 's'}`);
  }
  if (unsnapshotted) {
    parts.push(`${unsnapshotted} missing snapshot${unsnapshotted === 1 ? '' : 's'}`);
  }
  if (schemaBreaking) {
    parts.push(`${schemaBreaking} breaking schema drift${schemaBreaking === 1 ? '' : 's'}`);
  }
  if (schemaCompatible) {
    parts.push(`${schemaCompatible} schema-compatible drift${schemaCompatible === 1 ? '' : 's'}`);
  }
  return parts.length
    ? parts.join(' · ')
    : 'Current catalog dependencies are snapshotted and aligned.';
}

function draftDependencyCountRows(counts, label) {
  return Object.entries(counts || {})
    .filter(([, count]) => Number(count) > 0)
    .sort(([left], [right]) => String(left).localeCompare(String(right)))
    .map(([key, count]) => `
      <div class="library-impact-code ${escapeHtml(draftDependencyCountLevel(label, key))}">
        <strong>${escapeHtml(count)}</strong>
        <span>${escapeHtml(`${draftDependencyCountLabel(label, key)} ${label}`)}</span>
      </div>
    `).join('');
}

function draftDependencyCountLabel(label, key) {
  if (label === 'library') {
    return String(key || '');
  }
  if (label === 'schema') {
    return draftDependencySchemaCompatibilityLabel(key);
  }
  return operatorPaletteFacetLabel(key);
}

function draftDependencyCountLevel(label, key) {
  const normalized = String(key || '').trim().toUpperCase().replaceAll('-', '_');
  if (label === 'schema') {
    if (normalized === 'BREAKING') {
      return 'error';
    }
    return normalized === 'COMPATIBLE' ? 'warning' : 'success';
  }
  if (normalized === 'CATALOG_MISSING'
      || normalized === 'SCOPE_MISMATCH'
      || normalized === 'CATALOG_REPAIR_REQUIRED') {
    return 'error';
  }
  if (label === 'readiness' && normalized !== 'RUNTIME_EXECUTABLE') {
    return 'warning';
  }
  return 'success';
}

function draftDependencyOperatorRows(report) {
  const operators = Array.isArray(report?.operators) ? report.operators : [];
  const sorted = [...operators].sort((left, right) =>
    draftDependencyRowRank(right) - draftDependencyRowRank(left)
      || String(left.operatorRef || '').localeCompare(String(right.operatorRef || '')));
  const rows = sorted.slice(0, 6).map((operator) => `
    <div class="library-impact-risk ${escapeHtml(draftDependencyFingerprintLevel(operator.fingerprintState, operator.runtimeReadinessState, operator.schemaCompatibilityState))}">
      <strong>${escapeHtml(operator.operatorRef || 'operator')}</strong>
      <span>${escapeHtml(draftDependencyOperatorSummary(operator))}</span>
      <small>${draftDependencyNodeButtons(operator.nodeIds)}</small>
    </div>
  `).join('');
  const hidden = Math.max(0, sorted.length - 6);
  return rows + (hidden ? `<div class="library-impact-more">+${hidden} more operator dependencies</div>` : '');
}

function draftDependencyNodeRows(report) {
  const nodes = Array.isArray(report?.nodes) ? report.nodes : [];
  const interesting = nodes
    .filter((node) => draftDependencyRowRank(node) > 0 || (node.upstreamNodes || []).length || (node.downstreamNodes || []).length)
    .sort((left, right) => draftDependencyRowRank(right) - draftDependencyRowRank(left)
      || String(left.nodeId || '').localeCompare(String(right.nodeId || '')));
  const rows = interesting.slice(0, 5).map((node) => `
    <div class="library-impact-risk ${escapeHtml(draftDependencyFingerprintLevel(node.fingerprintState, node.runtimeReadinessState, node.schemaCompatibilityState))}">
      <strong>${draftDependencyNodeButton(node.nodeId || 'node')}</strong>
      <span>${escapeHtml(node.operatorRef || 'operator')} · ${escapeHtml(draftDependencyLineageLabel(node))}</span>
      <small>${escapeHtml(draftDependencyNodeSummary(node))}${draftDependencyRebaseButton(node)}</small>
    </div>
  `).join('');
  const hidden = Math.max(0, interesting.length - 5);
  return rows + (hidden ? `<div class="library-impact-more">+${hidden} more node dependencies</div>` : '');
}

function draftDependencyNodeButtons(nodeIds) {
  const ids = uniqueStrings(nodeIds);
  if (!ids.length) {
    return 'nodes none';
  }
  const visible = ids.slice(0, 3).map((nodeId) => draftDependencyNodeButton(nodeId)).join(' ');
  const hidden = Math.max(0, ids.length - 3);
  return `nodes ${visible}${hidden ? ` +${hidden} more` : ''}`;
}

function draftDependencyNodeButton(nodeId) {
  const id = String(nodeId || '').trim();
  if (!id) {
    return '';
  }
  return `<button class="diagnostic-focus" type="button" data-draft-dependency-node="${escapeHtml(id)}">${escapeHtml(id)}</button>`;
}

function draftDependencyRebaseButton(node) {
  const nodeId = String(node?.nodeId || '').trim();
  if (!nodeId || !draftDependencyHasRebaseState(node)) {
    return '';
  }
  const loading = state.operatorFingerprintRebaseNodeId === nodeId;
  const reason = operatorFingerprintRebaseBlockReason();
  const disabled = loading || Boolean(reason);
  return ` <button class="secondary compact" type="button" data-draft-dependency-rebase="${escapeHtml(nodeId)}" ${disabled ? 'disabled' : ''} title="${escapeHtml(reason || `Rebase ${nodeId} to the current operator fingerprint`)}">${loading ? 'Rebasing' : 'Rebase'}</button>${reason ? ` <em>${escapeHtml(reason)}</em>` : ''}`;
}

function draftDependencyCanRebase(row) {
  return draftDependencyHasRebaseState(row) && !operatorFingerprintRebaseBlockReason();
}

function draftDependencyHasRebaseState(row) {
  if (!state.currentDraftId || !state.currentDraftRevision) {
    return false;
  }
  const fingerprintState = String(row?.fingerprintState || '').toLowerCase();
  const readiness = String(row?.runtimeReadinessState || '').toUpperCase();
  return ['drifted', 'missing-snapshot'].includes(fingerprintState)
    && !['CATALOG_MISSING', 'SCOPE_MISMATCH'].includes(readiness);
}

function draftDependencyRowRank(row) {
  const fingerprintState = String(row?.fingerprintState || '').toLowerCase();
  const readiness = String(row?.runtimeReadinessState || '').toUpperCase();
  const schemaState = String(row?.schemaCompatibilityState || '').toLowerCase();
  if (fingerprintState === 'catalog-missing'
      || fingerprintState === 'scope-mismatch'
      || schemaState === 'breaking'
      || readiness === 'CATALOG_MISSING'
      || readiness === 'SCOPE_MISMATCH'
      || readiness === 'CATALOG_REPAIR_REQUIRED') {
    return 4;
  }
  if (fingerprintState === 'drifted' || schemaState === 'compatible') {
    return 3;
  }
  if (fingerprintState === 'missing-snapshot'
      || ['RUNTIME_BLOCKED', 'GOVERNANCE_REVIEW', 'DESIGN_ONLY'].includes(readiness)) {
    return 2;
  }
  return 0;
}

function draftDependencyFingerprintLevel(fingerprintState, runtimeReadinessState, schemaCompatibilityState = '') {
  const stateLabel = String(fingerprintState || '').toLowerCase();
  const readiness = String(runtimeReadinessState || '').toUpperCase();
  const schemaState = String(schemaCompatibilityState || '').toLowerCase();
  if (stateLabel === 'catalog-missing'
      || stateLabel === 'scope-mismatch'
      || schemaState === 'breaking'
      || readiness === 'CATALOG_MISSING'
      || readiness === 'SCOPE_MISMATCH'
      || readiness === 'CATALOG_REPAIR_REQUIRED') {
    return 'error';
  }
  if (stateLabel === 'drifted' || stateLabel === 'missing-snapshot'
      || schemaState === 'compatible'
      || ['DESIGN_ONLY', 'RUNTIME_BLOCKED', 'GOVERNANCE_REVIEW'].includes(readiness)) {
    return 'warning';
  }
  return 'success';
}

function draftDependencyOperatorSummary(operator) {
  return [
    operatorPaletteFacetLabel(operator.sourceKind || 'unknown'),
    draftDependencyOperatorLibraryLabel(operator.operatorLibraryId),
    operatorPaletteFacetLabel(operator.loweringMode || 'native'),
    operatorPaletteFacetLabel(operator.runtimeReadinessState || 'UNKNOWN'),
    draftDependencyFingerprintLabel(operator.fingerprintState),
    draftDependencySchemaCompatibilityLabel(operator.schemaCompatibilityState),
    draftDependencySchemaIssueLabel(operator),
    draftDependencyPolicyViolationLabel(operator)
  ].filter(Boolean).join(' · ');
}

function draftDependencyFingerprintLabel(value) {
  return {
    'catalog-missing': 'catalog missing',
    'scope-mismatch': 'scope mismatch',
    'missing-snapshot': 'missing snapshot',
    drifted: 'fingerprint drifted',
    current: 'fingerprint current'
  }[String(value || '').toLowerCase()] || String(value || 'unknown');
}

function draftDependencyLineageLabel(node) {
  const upstream = uniqueStrings(node?.upstreamNodes);
  const downstream = uniqueStrings(node?.downstreamNodes);
  return `${upstream.length} upstream · ${downstream.length} downstream`;
}

function draftDependencyNodeSummary(node) {
  const binding = uniqueStrings(node?.bindingSourceNodes);
  const edges = uniqueStrings(node?.edgeSourceNodes);
  const bindingTargets = uniqueStrings(node?.bindingTargetNodes);
  const edgeTargets = uniqueStrings(node?.edgeTargetNodes);
  const parts = [
    binding.length ? `binding from: ${binding.join(', ')}` : '',
    edges.length ? `edge from: ${edges.join(', ')}` : '',
    bindingTargets.length ? `binding to: ${bindingTargets.join(', ')}` : '',
    edgeTargets.length ? `edge to: ${edgeTargets.join(', ')}` : '',
    draftDependencyOperatorLibraryLabel(node?.operatorLibraryId),
    draftDependencyFingerprintLabel(node?.fingerprintState),
    draftDependencySchemaCompatibilityLabel(node?.schemaCompatibilityState),
    draftDependencySchemaIssueLabel(node),
    draftDependencyPolicyViolationLabel(node)
  ].filter(Boolean);
  return parts.join(' · ');
}

function draftDependencySchemaCompatibilityLabel(value) {
  return {
    breaking: 'schema breaking',
    compatible: 'schema compatible',
    current: 'schema current',
    'catalog-missing': 'schema catalog missing',
    'scope-mismatch': 'schema scope mismatch',
    'missing-snapshot': 'schema snapshot missing'
  }[String(value || '').toLowerCase()] || String(value || '');
}

function draftDependencySchemaIssueLabel(row) {
  const issues = Array.isArray(row?.schemaCompatibilityIssues) ? row.schemaCompatibilityIssues : [];
  if (!issues.length) {
    return '';
  }
  const first = issues[0] || {};
  const surface = [first.surface, first.portName].filter(Boolean).join(' ');
  const prefix = surface ? `schema ${surface}` : 'schema';
  const hidden = Math.max(0, issues.length - 1);
  return `${prefix} ${first.compatibility || 'review'}: ${first.message || 'review schema drift'}${hidden ? `; +${hidden} more` : ''}`;
}

function draftDependencyOperatorLibraryLabel(operatorLibraryId) {
  const value = String(operatorLibraryId || '').trim();
  return value ? `library ${value}` : '';
}

function draftDependencyPolicyViolationLabel(row) {
  const violations = uniqueStrings(row?.policyViolations);
  if (!violations.length) {
    return '';
  }
  const visible = violations.slice(0, 2).join('; ');
  const hidden = Math.max(0, violations.length - 2);
  return `scope ${visible}${hidden ? `; +${hidden} more` : ''}`;
}

function renderDraftStatus() {
  const target = $('draft-status');
  if (!target) return;
  const current = state.previewingDraftRevision
    ? `Previewing ${state.currentDraftId}@${state.previewingDraftRevision}; current server revision is @${state.currentDraftRevision || 0}`
    : state.currentDraftId
    ? `Current ${state.currentDraftId}@${state.currentDraftRevision || 0}`
    : 'Unsaved draft';
  const message = state.draftMessage?.text || current;
  target.hidden = false;
  target.textContent = message;
  target.className = `draft-status ${state.draftMessage?.level || 'info'}`;
}

function setDraftMessage(text, level = 'info') {
  state.draftMessage = text ? { text, level } : null;
  renderDraftStatus();
}

function renderPublicationControls() {
  const select = $('publication-select');
  if (!select) return;
  const artifactFilter = $('publication-artifact-filter');
  if (artifactFilter) {
    artifactFilter.innerHTML = [
      '<option value="">All artifacts</option>',
      '<option value="EXECUTABLE">Executable</option>',
      '<option value="DESIGN">Design</option>'
    ].join('');
    artifactFilter.value = normalizePublicationArtifactKindFilter(state.publicationArtifactKindFilter || '');
    artifactFilter.onchange = async () => {
      state.publicationArtifactKindFilter = normalizePublicationArtifactKindFilter(artifactFilter.value || '');
      state.selectedPublicationId = '';
      state.selectedGoldenCaseId = '';
      state.goldenAssertions = [];
      await loadPublicationList({ render: false });
      await loadGoldenCases({ render: false });
      await loadGoldenCertificationStatus({ render: false });
      renderPublicationControls();
    };
  }
  const options = state.publications.length
    ? state.publications.map((publication) => {
      const selected = publication.publicationId === state.selectedPublicationId ? ' selected' : '';
      return `<option value="${escapeHtml(publication.publicationId)}"${selected}>${escapeHtml(publicationOptionLabel(publication))}</option>`;
    })
    : ['<option value="">No publications</option>'];
  select.innerHTML = options.join('');
  select.disabled = !state.publications.length;
  select.onchange = async () => {
    state.selectedPublicationId = select.value;
    state.publicationMessage = null;
    state.selectedGoldenCaseId = '';
    state.goldenAssertions = [];
    await loadSelectedPublicationDetails({ render: false });
    await loadGoldenCases({ render: false });
    await loadGoldenCertificationStatus({ render: false });
    renderPublicationControls();
  };

  const runButton = $('run-publication');
  const reloadButton = $('reload-publications');
  const exportButton = $('export-publication');
  const validateButton = $('validate-publication-bundle');
  const importButton = $('import-publication');
  const bundleEditor = $('publication-bundle-json');
  const executablePublicationSelected = selectedPublicationExecutable();
  if (runButton) {
    runButton.disabled = !executablePublicationSelected;
    runButton.onclick = runSelectedPublication;
    runButton.title = state.selectedPublicationId && !executablePublicationSelected
      ? 'Design artifacts are schema snapshots and cannot be run.'
      : '';
  }
  if (reloadButton) {
    reloadButton.onclick = async () => {
      await loadPublicationList({ render: false });
      await loadSelectedPublicationDetails({ render: false });
      await loadGoldenCases({ render: false });
      await loadGoldenCertificationStatus({ render: false });
      renderPublicationControls();
    };
  }
  if (exportButton) {
    exportButton.disabled = !state.selectedPublicationId;
    exportButton.onclick = exportSelectedPublication;
  }
  if (validateButton) {
    validateButton.disabled = !state.publicationBundleText.trim();
    validateButton.onclick = validatePublicationBundle;
  }
  if (importButton) {
    importButton.disabled = !state.publicationBundleText.trim();
    importButton.onclick = importPublicationBundle;
  }
  if (bundleEditor) {
    bundleEditor.value = state.publicationBundleText;
    bundleEditor.oninput = () => {
      state.publicationBundleText = bundleEditor.value;
      for (const buttonId of ['validate-publication-bundle', 'import-publication']) {
        const button = $(buttonId);
        if (button) {
          button.disabled = !state.publicationBundleText.trim();
        }
      }
    };
  }
  renderPublicationAssetSummary();
  renderGoldenCaseControls();
  renderGoldenCertificationStatus();
  renderPublicationStatus();
  renderPublicationReadinessReview();
  renderPublicationDependencyReport();
}

function renderGoldenCaseControls() {
  const select = $('golden-case-select');
  const saveButton = $('save-golden-case');
  const runButton = $('run-golden-case');
  const deleteButton = $('delete-golden-case');
  const suiteButton = $('run-golden-suite');
  const certifyButton = $('certify-golden-suite');
  if (!select || !saveButton || !runButton || !deleteButton || !suiteButton || !certifyButton) return;
  const options = state.goldenCases.length
    ? state.goldenCases.map((testCase) => {
      const selected = testCase.caseId === state.selectedGoldenCaseId ? ' selected' : '';
      return `<option value="${escapeHtml(testCase.caseId)}"${selected}>${escapeHtml(goldenCaseOptionLabel(testCase))}</option>`;
    })
    : ['<option value="">No golden cases</option>'];
  select.innerHTML = options.join('');
  select.disabled = !state.goldenCases.length;
  select.onchange = () => {
    state.selectedGoldenCaseId = select.value;
  };
  const executablePublicationSelected = selectedPublicationExecutable();
  saveButton.disabled = !executablePublicationSelected;
  saveButton.onclick = saveGoldenCaseFromCurrentOutput;
  runButton.disabled = !executablePublicationSelected || !state.selectedGoldenCaseId;
  runButton.onclick = runSelectedGoldenCase;
  deleteButton.disabled = !state.selectedGoldenCaseId;
  deleteButton.onclick = deleteSelectedGoldenCase;
  suiteButton.disabled = !executablePublicationSelected;
  suiteButton.onclick = runPublicationGoldenSuite;
  certifyButton.disabled = !executablePublicationSelected;
  certifyButton.onclick = certifyPublicationGoldenSuite;
  renderGoldenAssertionControls();
}

function renderGoldenAssertionControls() {
  const modeSelect = $('golden-assertion-mode');
  const pathInput = $('golden-assertion-path');
  const valueInput = $('golden-assertion-value');
  const addButton = $('add-golden-assertion');
  const clearButton = $('clear-golden-assertions');
  const listTarget = $('golden-assertion-list');
  if (!modeSelect || !pathInput || !valueInput || !addButton || !clearButton || !listTarget) return;
  const modes = [
    ['EXACT_OUTPUT', 'Exact output'],
    ['OUTPUT_EQUALS', 'Output equals'],
    ['OUTPUT_MATCHES_SCHEMA', 'Output matches schema'],
    ['PATH_EQUALS', 'Path equals'],
    ['PATH_APPROX_EQUALS', 'Path approx equals'],
    ['PATH_EXISTS', 'Path exists'],
    ['PATH_ABSENT', 'Path absent']
  ];
  modeSelect.innerHTML = modes.map(([value, label]) => {
    const selected = state.goldenAssertionMode === value ? ' selected' : '';
    return `<option value="${escapeHtml(value)}"${selected}>${escapeHtml(label)}</option>`;
  }).join('');
  const executablePublicationSelected = selectedPublicationExecutable();
  modeSelect.disabled = !executablePublicationSelected;
  modeSelect.onchange = () => {
    state.goldenAssertionMode = modeSelect.value || 'EXACT_OUTPUT';
    renderGoldenAssertionControls();
  };

  const pathMode = state.goldenAssertionMode === 'PATH_EQUALS'
    || state.goldenAssertionMode === 'PATH_APPROX_EQUALS'
    || state.goldenAssertionMode === 'PATH_EXISTS'
    || state.goldenAssertionMode === 'PATH_ABSENT';
  const valueMode = state.goldenAssertionMode === 'OUTPUT_EQUALS'
    || state.goldenAssertionMode === 'OUTPUT_MATCHES_SCHEMA'
    || state.goldenAssertionMode === 'PATH_APPROX_EQUALS'
    || state.goldenAssertionMode === 'PATH_EQUALS';
  pathInput.value = state.goldenAssertionPath;
  pathInput.disabled = !executablePublicationSelected || !pathMode;
  pathInput.oninput = () => {
    state.goldenAssertionPath = pathInput.value;
  };
  valueInput.value = state.goldenAssertionValueText;
  valueInput.disabled = !executablePublicationSelected || !valueMode;
  valueInput.placeholder = state.goldenAssertionMode === 'OUTPUT_MATCHES_SCHEMA'
    ? 'JSON schema, blank infers from last output'
    : state.goldenAssertionMode === 'PATH_APPROX_EQUALS'
    ? '{"value": 720, "tolerance": 0.01}'
    : valueMode ? 'Expected JSON value' : '';
  valueInput.oninput = () => {
    state.goldenAssertionValueText = valueInput.value;
  };
  const queuedAssertions = Array.isArray(state.goldenAssertions) ? state.goldenAssertions : [];
  addButton.disabled = !executablePublicationSelected || state.goldenAssertionMode === 'EXACT_OUTPUT';
  addButton.onclick = appendGoldenAssertionFromControls;
  clearButton.disabled = !queuedAssertions.length;
  clearButton.onclick = clearGoldenAssertions;
  renderGoldenAssertionList(listTarget, queuedAssertions);
}

function renderGoldenAssertionList(target, assertions) {
  const queued = Array.isArray(assertions) ? assertions : [];
  if (!queued.length) {
    target.innerHTML = '<div class="golden-assertion-empty">No queued assertions</div>';
    return;
  }
  target.innerHTML = queued.map((assertion, index) => `
    <div class="golden-assertion-row">
      <span>
        <strong>${escapeHtml(index + 1)}. ${escapeHtml(goldenAssertionModeLabel(assertion.mode))}</strong>
        <small>${escapeHtml(goldenAssertionExpectedSummary(assertion))}</small>
      </span>
      <button class="secondary compact danger" type="button" data-remove-golden-assertion="${escapeHtml(index)}">Remove</button>
    </div>
  `).join('');
  target.querySelectorAll('[data-remove-golden-assertion]').forEach((button) => {
    button.addEventListener('click', () => removeGoldenAssertion(Number(button.dataset.removeGoldenAssertion)));
  });
}

function goldenAssertionModeLabel(mode) {
  switch (mode) {
    case 'OUTPUT_EQUALS':
      return 'Output equals';
    case 'OUTPUT_MATCHES_SCHEMA':
      return 'Output matches schema';
    case 'PATH_EQUALS':
      return 'Path equals';
    case 'PATH_APPROX_EQUALS':
      return 'Path approx equals';
    case 'PATH_EXISTS':
      return 'Path exists';
    case 'PATH_ABSENT':
      return 'Path absent';
    default:
      return mode || 'Assertion';
  }
}

function goldenAssertionExpectedSummary(assertion) {
  const path = assertion.path ? assertion.path : 'output';
  if (assertion.expectedValue === null || assertion.expectedValue === undefined) {
    return path;
  }
  const summary = JSON.stringify(assertion.expectedValue);
  const compact = summary && summary.length > 96 ? `${summary.slice(0, 93)}...` : summary;
  return `${path} · ${compact || ''}`;
}

function appendGoldenAssertionFromControls() {
  if (!state.lastPayload || !Object.prototype.hasOwnProperty.call(state.lastPayload, 'data')) {
    setPublicationMessage('Run the publication before adding assertions.', 'error');
    return;
  }
  try {
    const assertions = currentGoldenAssertionsFromControls(state.lastPayload.data);
    if (!assertions.length) {
      state.goldenAssertions = [];
      setPublicationMessage('Using exact-output golden fallback.', 'info');
    } else {
      state.goldenAssertions = [
        ...(Array.isArray(state.goldenAssertions) ? state.goldenAssertions : []),
        ...assertions.map(cloneGoldenAssertion)
      ];
      setPublicationMessage(`Queued ${state.goldenAssertions.length} assertion(s).`, 'success');
    }
  } catch (error) {
    setPublicationMessage(error.message, 'error');
  }
  renderGoldenAssertionControls();
}

function removeGoldenAssertion(index) {
  const queued = Array.isArray(state.goldenAssertions) ? [...state.goldenAssertions] : [];
  if (Number.isInteger(index) && index >= 0 && index < queued.length) {
    queued.splice(index, 1);
  }
  state.goldenAssertions = queued;
  renderGoldenAssertionControls();
}

function clearGoldenAssertions() {
  state.goldenAssertions = [];
  renderGoldenAssertionControls();
}

function goldenCaseOptionLabel(testCase) {
  const name = testCase.name || 'Golden case';
  const id = shortRunId(testCase.caseId || '');
  return id ? `${name} · ${id}` : name;
}

function renderGoldenCertificationStatus() {
  const target = $('golden-certification-status');
  if (!target) return;
  const status = state.goldenCertificationStatus;
  const certification = state.goldenCertification;
  target.hidden = false;
  if (!state.selectedPublicationId) {
    target.textContent = 'No publication selected';
    target.className = 'certification-status neutral';
    return;
  }
  if (status) {
    const passedCases = status.certification ? Number(status.certification.passedCases) || 0 : 0;
    const totalCases = Number(status.caseCount) || Number(status.certification?.totalCases) || 0;
    const time = status.certification?.certifiedAt
      ? ` · ${new Date(status.certification.certifiedAt).toLocaleString()}`
      : '';
    target.textContent = `${goldenCertificationStatusLabel(status)} (${passedCases}/${totalCases})${time}`;
    target.className = `certification-status ${goldenCertificationStatusClass(status)}`;
    return;
  }
  if (!certification) {
    target.textContent = 'Not certified';
    target.className = 'certification-status neutral';
    return;
  }
  const passedCases = Number(certification.passedCases) || 0;
  const totalCases = Number(certification.totalCases) || 0;
  const label = certification.certified ? 'Certified' : 'Certification failed';
  const time = certification.certifiedAt ? ` · ${new Date(certification.certifiedAt).toLocaleString()}` : '';
  target.textContent = `${label} (${passedCases}/${totalCases})${time}`;
  target.className = `certification-status ${certification.certified ? 'success' : 'error'}`;
}

function goldenCertificationStatusLabel(status) {
  switch (status.status) {
    case 'CERTIFIED':
      return status.promotionReady ? 'Promotion ready' : 'Certified';
    case 'STALE':
      return 'Certification stale';
    case 'FAILED':
      return 'Certification failed';
    case 'MISSING_CASES':
      return 'Missing golden cases';
    case 'UNCERTIFIED':
      return 'Not certified';
    default:
      return status.status || 'Certification status';
  }
}

function goldenCertificationStatusClass(status) {
  if (status.promotionReady) return 'success';
  if (status.status === 'STALE' || status.status === 'UNCERTIFIED' || status.status === 'MISSING_CASES') {
    return 'warning';
  }
  return 'error';
}

function publicationOptionLabel(publication) {
  const revision = publication.draftRevision || publication.draft?.revision || 0;
  const graph = publication.graphName || publication.draft?.graphName || publication.publicationId;
  const artifactKind = normalizePublishArtifactKind(publication.artifactKind || 'EXECUTABLE');
  const readiness = publicationListReadinessLabel(publication);
  return [`${graph} @${revision}`, artifactKind, readiness, publication.publicationId]
    .filter(Boolean)
    .join(' · ');
}

function publicationListReadinessLabel(publication) {
  const readiness = publicationReadiness(publication);
  return readiness?.state ? operatorPaletteFacetLabel(readiness.state) : '';
}

function publicationAssetSummary(publications) {
  const summary = {
    total: 0,
    executableArtifactCount: 0,
    designArtifactCount: 0,
    runtimeExecutableCount: 0,
    designOnlyCount: 0,
    runtimeBlockedCount: 0,
    governanceReviewCount: 0,
    repairRequiredCount: 0,
    unknownReadinessCount: 0
  };
  for (const publication of Array.isArray(publications) ? publications : []) {
    summary.total += 1;
    const artifactKind = normalizePublishArtifactKind(publication?.artifactKind || 'EXECUTABLE');
    if (artifactKind === 'DESIGN') {
      summary.designArtifactCount += 1;
    } else {
      summary.executableArtifactCount += 1;
    }
    const state = publicationReadiness(publication)?.state || '';
    switch (state) {
      case 'runtime-executable':
        summary.runtimeExecutableCount += 1;
        break;
      case 'design-only':
        summary.designOnlyCount += 1;
        break;
      case 'runtime-blocked':
        summary.runtimeBlockedCount += 1;
        break;
      case 'governance-review':
        summary.governanceReviewCount += 1;
        break;
      case 'draft-repair-required':
      case 'catalog-repair-required':
        summary.repairRequiredCount += 1;
        break;
      default:
        summary.unknownReadinessCount += 1;
        break;
    }
  }
  return summary;
}

function publicationAssetSummaryLevel(summary) {
  if (!summary || !summary.total) {
    return 'info';
  }
  if (summary.repairRequiredCount) {
    return 'error';
  }
  if (summary.runtimeBlockedCount || summary.governanceReviewCount) {
    return 'warning';
  }
  return 'success';
}

function publicationAssetSummaryRows(publications, limit = 5) {
  const rows = publicationAssetInterestingPublications(publications)
    .map((publication) => ({
      label: publicationOptionLabel(publication),
      value: publicationReadinessStatusText(publication) || 'No frozen readiness snapshot'
    }));
  return rows.slice(0, Math.max(0, Number(limit) || 0));
}

function publicationAssetInterestingPublications(publications) {
  return (Array.isArray(publications) ? publications : [])
    .filter((publication) => normalizePublishArtifactKind(publication?.artifactKind || 'EXECUTABLE') === 'DESIGN'
      || (publicationReadiness(publication)?.state || '') !== 'runtime-executable');
}

function renderPublicationAssetSummary() {
  const target = $('publication-asset-summary');
  if (!target) return;
  const publications = Array.isArray(state.publications) ? state.publications : [];
  if (!publications.length) {
    target.hidden = true;
    target.innerHTML = '';
    return;
  }
  const summary = publicationAssetSummary(publications);
  const interestingPublicationCount = publicationAssetInterestingPublications(publications).length;
  const rows = publicationAssetSummaryRows(publications);
  const overflow = Math.max(0, interestingPublicationCount - rows.length);
  const stats = [
    ['Total', summary.total],
    ['EXECUTABLE', summary.executableArtifactCount],
    ['DESIGN', summary.designArtifactCount],
    ['Runtime executable', summary.runtimeExecutableCount],
    ['Design only', summary.designOnlyCount],
    ['Runtime blocked', summary.runtimeBlockedCount],
    ['Governance review', summary.governanceReviewCount],
    ['Repair required', summary.repairRequiredCount]
  ].filter(([, value], index) => index < 3 || value)
    .map(([label, value]) => `<span><strong>${escapeHtml(value)}</strong> ${escapeHtml(label)}</span>`)
    .join('');
  target.hidden = false;
  target.className = `library-impact-panel ${escapeHtml(publicationAssetSummaryLevel(summary))}`;
  target.innerHTML = `
    <div class="library-impact-head">
      <strong>Published Artifact Index</strong>
      <span>${escapeHtml(`${summary.designArtifactCount} design / ${summary.executableArtifactCount} executable`)}</span>
    </div>
    <div class="library-impact-risk-summary">${escapeHtml('Frozen publication readiness is visible before selecting an artifact.')}</div>
    <div class="library-impact-stats">${stats}</div>
    ${rows.length ? `<div class="library-impact-risks">${rows.map((row) => `
      <div class="library-impact-risk ${escapeHtml(publicationAssetRowLevel(row.value))}">
        <strong>${escapeHtml(row.label)}</strong>
        <span>${escapeHtml(row.value)}</span>
      </div>
    `).join('')}${overflow ? `<div class="library-impact-more">+${overflow} more non-executable or review-required artifacts</div>` : ''}</div>` : ''}
  `;
}

function publicationAssetRowLevel(value) {
  const text = String(value || '').toLowerCase();
  if (text.includes('repair')) return 'error';
  if (text.includes('blocked') || text.includes('governance')) return 'warning';
  return 'info';
}

function publicationReadiness(publication) {
  return normalizeVisualGraphReadiness(publication?.validation?.readiness || publication?.readiness);
}

function publicationReadinessStatusText(publication) {
  return visualGraphReadinessStatusText(publicationReadiness(publication));
}

function publicationReadinessReviewRows(publication, limit = 6) {
  const readiness = publicationReadiness(publication);
  if (!readiness) {
    return [];
  }
  const nodes = readiness.nodes.filter((node) =>
    (node.state && node.state !== 'runtime-executable')
      || node.diagnosticCount > 0
      || node.warningCount > 0
      || node.errorCount > 0);
  return nodes.slice(0, Math.max(0, Number(limit) || 0)).map((node) => ({
    label: publicationReadinessNodeLabel(publication, node),
    value: publicationReadinessNodeSummary(node)
  }));
}

function publicationReadinessNodeLabel(publication, node) {
  const draftNode = publication?.draft?.nodes?.find((candidate) => candidate.id === node.nodeId);
  const label = draftNode?.label || node.nodeId || node.operatorRef || 'node';
  const state = node.state ? operatorPaletteFacetLabel(node.state) : 'Readiness';
  return `${label} · ${state}`;
}

function publicationReadinessNodeSummary(node) {
  const parts = [
    node.operatorRef || '',
    node.summary || node.title || '',
    node.errorCount ? `${node.errorCount} error` : '',
    node.warningCount ? `${node.warningCount} warning` : ''
  ].filter(Boolean);
  return parts.join(' · ');
}

function renderPublicationReadinessReview() {
  const target = $('publication-readiness');
  if (!target) return;
  const publication = selectedPublication();
  const readiness = publicationReadiness(publication);
  if (!publication || !readiness) {
    target.hidden = true;
    target.innerHTML = '';
    return;
  }
  const reviewRows = publicationReadinessReviewRows(publication, Number.MAX_SAFE_INTEGER);
  const rows = reviewRows.slice(0, 6);
  const overflow = Math.max(0, reviewRows.length - rows.length);
  const status = publicationReadinessStatusText(publication) || readiness.summary || readiness.title;
  target.hidden = false;
  target.className = `operator-readiness-panel publication-readiness-panel ${escapeHtml(readiness.level || 'info')}`;
  target.innerHTML = `
    <div>
      <strong>${escapeHtml(readiness.title || operatorPaletteFacetLabel(readiness.state) || 'Publication readiness')}</strong>
      <span>${escapeHtml(status)}</span>
    </div>
    ${rows.length ? `<div class="operator-readiness-rows">${rows.map((row) => `
      <div class="operator-readiness-row">
        <strong>${escapeHtml(row.label)}</strong>
        <span>${escapeHtml(row.value)}</span>
      </div>
    `).join('')}${overflow ? `
      <div class="operator-readiness-row">
        <strong>${escapeHtml(`${overflow} more`)}</strong>
        <span>${escapeHtml('See frozen validation for the full node readiness list.')}</span>
      </div>
    ` : ''}</div>` : ''}
  `;
}

function renderPublicationDependencyReport() {
  const target = $('publication-dependencies');
  if (!target) return;
  const publication = selectedPublication();
  const report = publication?.dependencyReport || null;
  if (!publication || !report || !Array.isArray(report.nodes)) {
    target.hidden = true;
    target.innerHTML = '';
    return;
  }
  const level = draftDependencyReportLevel(report);
  const stats = [
    ['Operators', report.operatorDependencyCount || 0],
    ['Nodes', report.nodeCount || 0],
    ['Missing', report.missingOperatorCount || 0],
    ['Scope', report.scopeMismatchOperatorCount || 0],
    ['Drifted', report.driftedFingerprintCount || 0],
    ['Unsnapshotted', report.missingFingerprintCount || 0],
    ['Schema break', report.schemaBreakingDriftCount || 0],
    ['Schema review', report.schemaCompatibleDriftCount || 0]
  ].map(([label, value]) => `<span><strong>${escapeHtml(value)}</strong> ${escapeHtml(label)}</span>`).join('');
  const readinessRows = draftDependencyCountRows(report.runtimeReadinessStateCounts || {}, 'readiness');
  const sourceRows = draftDependencyCountRows(report.sourceKindCounts || {}, 'source');
  const libraryRows = draftDependencyCountRows(report.operatorLibraryIdCounts || {}, 'library');
  const schemaRows = draftDependencyCountRows(report.schemaCompatibilityStateCounts || {}, 'schema');
  const operatorRows = publicationDependencyOperatorRows(report);
  const nodeRows = publicationDependencyNodeRows(report);
  target.hidden = false;
  target.className = `library-impact-panel ${escapeHtml(level)}`;
  target.innerHTML = `
    <div class="library-impact-head">
      <strong>Frozen Dependencies</strong>
      <span>${escapeHtml(`${publication.publicationId || 'publication'} · ${publication.artifactKind || 'EXECUTABLE'}`)}</span>
    </div>
    <div class="library-impact-risk-summary">${escapeHtml(publicationDependencySummary(report))}</div>
    <div class="library-impact-stats">${stats}</div>
    ${readinessRows || sourceRows || libraryRows || schemaRows
      ? `<div class="library-impact-codes">${readinessRows}${sourceRows}${libraryRows}${schemaRows}</div>`
      : ''}
    ${operatorRows ? `<div class="library-impact-risks">${operatorRows}</div>` : ''}
    ${nodeRows ? `<div class="library-impact-risks">${nodeRows}</div>` : ''}
  `;
}

function publicationDependencySummary(report) {
  const base = draftDependencySummary(report);
  if (base === 'Current catalog dependencies are snapshotted and aligned.') {
    return 'Publish-time dependencies were snapshotted with this immutable artifact.';
  }
  return `Publish-time dependency review: ${base}`;
}

function publicationDependencyOperatorRows(report) {
  const operators = Array.isArray(report?.operators) ? report.operators : [];
  const sorted = [...operators].sort((left, right) =>
    draftDependencyRowRank(right) - draftDependencyRowRank(left)
      || String(left.operatorRef || '').localeCompare(String(right.operatorRef || '')));
  const rows = sorted.slice(0, 6).map((operator) => `
    <div class="library-impact-risk ${escapeHtml(draftDependencyFingerprintLevel(operator.fingerprintState, operator.runtimeReadinessState, operator.schemaCompatibilityState))}">
      <strong>${escapeHtml(operator.operatorRef || 'operator')}</strong>
      <span>${escapeHtml(draftDependencyOperatorSummary(operator))}</span>
      <small>${escapeHtml(`nodes ${uniqueStrings(operator.nodeIds).join(', ') || 'none'}`)}</small>
    </div>
  `).join('');
  const hidden = Math.max(0, sorted.length - 6);
  return rows + (hidden ? `<div class="library-impact-more">+${hidden} more frozen operator dependencies</div>` : '');
}

function publicationDependencyNodeRows(report) {
  const nodes = Array.isArray(report?.nodes) ? report.nodes : [];
  const interesting = nodes
    .filter((node) => draftDependencyRowRank(node) > 0 || (node.upstreamNodes || []).length || (node.downstreamNodes || []).length)
    .sort((left, right) => draftDependencyRowRank(right) - draftDependencyRowRank(left)
      || String(left.nodeId || '').localeCompare(String(right.nodeId || '')));
  const rows = interesting.slice(0, 5).map((node) => `
    <div class="library-impact-risk ${escapeHtml(draftDependencyFingerprintLevel(node.fingerprintState, node.runtimeReadinessState, node.schemaCompatibilityState))}">
      <strong>${escapeHtml(node.nodeId || 'node')}</strong>
      <span>${escapeHtml(node.operatorRef || 'operator')} · ${escapeHtml(draftDependencyLineageLabel(node))}</span>
      <small>${escapeHtml(draftDependencyNodeSummary(node))}</small>
    </div>
  `).join('');
  const hidden = Math.max(0, interesting.length - 5);
  return rows + (hidden ? `<div class="library-impact-more">+${hidden} more frozen node dependencies</div>` : '');
}

function selectedPublicationExecutable() {
  const publication = selectedPublication();
  return Boolean(publication)
    && normalizePublishArtifactKind(publication.artifactKind || 'EXECUTABLE') === 'EXECUTABLE';
}

function renderPublicationStatus() {
  const target = $('publication-status');
  if (!target) return;
  const selected = state.publications.find((publication) =>
    publication.publicationId === state.selectedPublicationId);
  const current = selected
    ? `Selected ${selected.publicationId} (${normalizePublishArtifactKind(selected.artifactKind || 'EXECUTABLE')})`
    : `${state.publications.length} published artifacts`;
  const message = state.publicationMessage?.text || current;
  target.hidden = false;
  target.textContent = message;
  target.className = `draft-status ${state.publicationMessage?.level || 'info'}`;
}

function setPublicationMessage(text, level = 'info') {
  state.publicationMessage = text ? { text, level } : null;
  renderPublicationStatus();
  renderPublicationReadinessReview();
}

function renderRunHistoryControls() {
  const source = $('run-history-source');
  const artifact = $('run-history-artifact');
  const outcome = $('run-history-outcome');
  const limit = $('run-history-limit');
  const reload = $('reload-run-history');
  if (!source || !artifact || !outcome || !limit || !reload) {
    return;
  }

  source.innerHTML = [
    ['','All sources'],
    ['TRANSIENT_DRAFT', 'Draft preview'],
    ['STORED_DRAFT', 'Saved draft'],
    ['PUBLICATION', 'Publication']
  ].map(([value, label]) => `<option value="${escapeHtml(value)}">${escapeHtml(label)}</option>`).join('');
  source.value = state.runHistoryFilters.sourceKind || '';
  source.onchange = () => {
    state.runHistoryFilters.sourceKind = source.value;
    if (source.value !== 'PUBLICATION') {
      state.runHistoryFilters.sourceArtifactKind = '';
    }
    loadRunHistory();
  };

  artifact.innerHTML = [
    ['', 'All artifacts'],
    ['EXECUTABLE', 'Executable'],
    ['DESIGN', 'Design']
  ].map(([value, label]) => `<option value="${escapeHtml(value)}">${escapeHtml(label)}</option>`).join('');
  artifact.value = state.runHistoryFilters.sourceArtifactKind || '';
  artifact.onchange = () => {
    state.runHistoryFilters.sourceArtifactKind = artifact.value;
    if (artifact.value && state.runHistoryFilters.sourceKind !== 'PUBLICATION') {
      state.runHistoryFilters.sourceKind = 'PUBLICATION';
    }
    loadRunHistory();
  };

  outcome.innerHTML = [
    ['', 'All outcomes'],
    ['true', 'Success'],
    ['false', 'Errors']
  ].map(([value, label]) => `<option value="${escapeHtml(value)}">${escapeHtml(label)}</option>`).join('');
  outcome.value = state.runHistoryFilters.outcome || '';
  outcome.onchange = () => {
    state.runHistoryFilters.outcome = outcome.value;
    loadRunHistory();
  };

  limit.value = state.runHistoryFilters.limit || '8';
  limit.onchange = () => {
    state.runHistoryFilters.limit = limit.value || '8';
    loadRunHistory();
  };
  reload.onclick = loadRunHistory;
  renderRunHistoryStatus();
  renderRunHistoryStats();
  renderRunHistoryNodeStats();
  renderRunHistoryList();
}

function renderRunHistoryStatus() {
  const target = $('run-history-status');
  if (!target) return;
  const message = state.runHistoryMessage?.text || `${state.runHistory.length} recent runs`;
  target.hidden = false;
  target.textContent = message;
  target.className = `draft-status ${state.runHistoryMessage?.level || 'info'}`;
}

function renderRunHistoryStats() {
  const target = $('run-history-stats');
  if (!target) return;
  const stats = state.runHistoryStats;
  if (!stats || !stats.totalRuns) {
    target.innerHTML = '<div class="run-history-empty">No SLO samples</div>';
    return;
  }
  const successRate = Math.round((Number(stats.successRate) || 0) * 100);
  target.innerHTML = [
    runHistoryStatHtml('Runs', stats.totalRuns),
    runHistoryStatHtml('Success', `${successRate}%`),
    runHistoryStatHtml('p95', `${stats.p95ElapsedMs || 0}ms`),
    runHistoryStatHtml('Blocked', stats.blockedRuns || 0),
    runHistoryStatHtml('Design', stats.bySourceArtifactKind?.DESIGN || 0)
  ].join('');
}

function runHistoryStatHtml(label, value) {
  return `
    <div class="run-history-stat">
      <span>${escapeHtml(label)}</span>
      <strong>${escapeHtml(value)}</strong>
    </div>
  `;
}

function renderRunHistoryNodeStats() {
  const target = $('run-history-node-stats');
  if (!target) return;
  const nodes = Array.isArray(state.runHistoryNodeStats?.nodes)
    ? state.runHistoryNodeStats.nodes
    : [];
  if (!nodes.length) {
    target.innerHTML = '';
    return;
  }
  const ranked = [...nodes]
    .sort((a, b) => {
      const issueDelta = ((Number(b.errorCount) || 0) * 100 + (Number(b.diagnosticCount) || 0))
        - ((Number(a.errorCount) || 0) * 100 + (Number(a.diagnosticCount) || 0));
      if (issueDelta) return issueDelta;
      return nodeP95ForDisplay(b) - nodeP95ForDisplay(a);
    })
    .slice(0, 3);
  target.innerHTML = ranked.map((node) => runHistoryNodeStatHtml(node)).join('');
}

function nodeP95ForDisplay(node) {
  return Number(node?.p95NodeElapsedMs) || Number(node?.p95ObservedElapsedMs) || 0;
}

function runHistoryNodeStatHtml(node) {
  const errors = Number(node.errorCount) || 0;
  const diagnostics = Number(node.diagnosticCount) || 0;
  const level = errors ? 'error' : diagnostics ? 'warning' : 'clean';
  const name = node.label || node.nodeId || 'node';
  const operator = node.operatorRef ? ` · ${node.operatorRef}` : '';
  const timingKnown = Number(node.timingKnownRuns) || 0;
  const p95 = nodeP95ForDisplay(node);
  const latencyLabel = timingKnown ? 'node p95' : 'observed p95';
  return `
    <div class="run-history-node-stat ${escapeHtml(level)}">
      <span>${escapeHtml(name)}${escapeHtml(operator)}</span>
      <small>${escapeHtml(node.runCount || 0)} runs · ${escapeHtml(errors)} err · ${escapeHtml(diagnostics)} diag · ${escapeHtml(latencyLabel)} ${escapeHtml(p95)}ms</small>
    </div>
  `;
}

function renderRunHistoryList() {
  const target = $('run-history-list');
  if (!target) return;
  if (!state.runHistory.length) {
    target.innerHTML = '<div class="run-history-empty">No matching runs</div>';
    return;
  }
  target.innerHTML = state.runHistory
    .map((record) => runHistoryRowHtml(record))
    .join('');
  target.querySelectorAll('[data-run-history-id]').forEach((button) => {
    button.addEventListener('click', () => openRunHistoryRecord(button.dataset.runHistoryId || ''));
  });
}

function runHistoryRowHtml(record) {
  const source = record.sourceKind || 'RUN';
  const artifact = record.sourceArtifactKind ? ` · ${record.sourceArtifactKind}` : '';
  const outcome = record.success ? 'success' : record.compiled ? 'error' : 'blocked';
  const reference = record.publicationId
    ? record.publicationId
    : record.draftId
    ? `${record.draftId}@${record.draftRevision || 0}`
    : 'transient';
  const diagnostics = Array.isArray(record.diagnostics) ? record.diagnostics.length : 0;
  const errors = Array.isArray(record.errors) ? record.errors.length : 0;
  const nodeCount = record.nodeSnapshots && typeof record.nodeSnapshots === 'object'
    ? Object.keys(record.nodeSnapshots).length
    : 0;
  const nodeNote = nodeCount ? `${nodeCount} nodes · ` : '';
  return `
    <button class="run-history-row ${escapeHtml(outcome)}" type="button" data-run-history-id="${escapeHtml(record.runId || '')}">
      <span class="run-history-main">
        <strong>${escapeHtml(record.graphName || 'unnamedGraph')}</strong>
        <small>${escapeHtml(source)}${escapeHtml(artifact)} · ${escapeHtml(reference)}</small>
      </span>
      <span class="run-history-meta">
        <span>${escapeHtml(outcome)}</span>
        <small>${escapeHtml(shortRunId(record.runId || ''))} · ${escapeHtml(record.elapsedMs || 0)}ms · ${escapeHtml(nodeNote)}${diagnostics + errors} notes</small>
      </span>
    </button>
  `;
}

function shortRunId(runId) {
  return runId && runId.length > 8 ? runId.slice(0, 8) : runId;
}

async function openRunHistoryRecord(runId) {
  if (!runId) return;
  try {
    const [recordResponse, traceResponse] = await Promise.all([
      fetch(`/api/visual/runs/${encodeURIComponent(runId)}`),
      fetch(`/api/visual/runs/${encodeURIComponent(runId)}/trace`)
    ]);
    if (!recordResponse.ok) {
      throw new Error(`Run ${runId} failed with ${recordResponse.status}`);
    }
    if (!traceResponse.ok) {
      throw new Error(`Run trace ${runId} failed with ${traceResponse.status}`);
    }
    const [record, trace] = await Promise.all([
      recordResponse.json(),
      traceResponse.json()
    ]);
    state.activeRunTrace = trace;
    state.activeRunTraceId = runId;
    const traceSummary = runTraceSummary(trace);
    const traceCoverage = runTraceCanvasCoverage(trace, state.builder, state.layout);
    $('output').textContent = pretty({
      runHistory: record,
      runTrace: trace,
      runTraceSummary: traceSummary,
      runTraceCoverage: traceCoverage
    });
    state.runHistoryMessage = {
      text: `Loaded ${shortRunId(runId)}: ${traceSummary.nodeCount} nodes, ${traceSummary.diagnosticCount} node diagnostics, ${runTraceCoverageText(traceCoverage)}.`,
      level: traceCoverage.unmatchedNodeIds.length ? 'warning' : 'success'
    };
  } catch (error) {
    clearActiveRunTrace();
    state.runHistoryMessage = { text: error.message, level: 'error' };
  }
  renderDiagram();
  renderRunHistoryStatus();
}

function runTraceSummary(trace) {
  const nodes = Array.isArray(trace?.nodes) ? trace.nodes : [];
  const diagnosticCount = nodes.reduce((total, node) => total + (Number(node.diagnosticCount) || 0), 0);
  const errorCount = nodes.reduce((total, node) => total + (Number(node.errorCount) || 0), 0);
  const selected = nodes.find((node) => node.outputSelected);
  return {
    nodeCount: nodes.length,
    diagnosticCount,
    errorCount,
    selectedOutputNode: selected?.nodeId || trace?.outputNode || ''
  };
}

async function loadRunHistory(options = {}) {
  try {
    const [historyResponse, statsResponse, nodeStatsResponse] = await Promise.all([
      fetch(runHistoryUrl()),
      fetch(runHistoryStatsUrl()),
      fetch(runHistoryNodeStatsUrl())
    ]);
    if (!historyResponse.ok) {
      throw new Error(`Run history failed with ${historyResponse.status}`);
    }
    if (!statsResponse.ok) {
      throw new Error(`Run history stats failed with ${statsResponse.status}`);
    }
    if (!nodeStatsResponse.ok) {
      throw new Error(`Run history node stats failed with ${nodeStatsResponse.status}`);
    }
    state.runHistory = await historyResponse.json();
    state.runHistoryStats = await statsResponse.json();
    state.runHistoryNodeStats = await nodeStatsResponse.json();
    state.runHistoryMessage = null;
  } catch (error) {
    state.runHistory = [];
    state.runHistoryStats = null;
    state.runHistoryNodeStats = null;
    state.runHistoryMessage = { text: error.message, level: 'error' };
  }
  if (options.render !== false) {
    renderRunHistoryControls();
  }
  return state.runHistory;
}

function runHistoryUrl() {
  return runHistoryUrlFor('/api/visual/runs');
}

function runHistoryStatsUrl() {
  return runHistoryUrlFor('/api/visual/runs/stats');
}

function runHistoryNodeStatsUrl() {
  return runHistoryUrlFor('/api/visual/runs/node-stats');
}

function runHistoryUrlFor(path) {
  const params = new URLSearchParams();
  const filters = state.runHistoryFilters || {};
  if (filters.sourceKind) {
    params.set('sourceKind', filters.sourceKind);
  }
  if (filters.sourceArtifactKind) {
    params.set('sourceArtifactKind', filters.sourceArtifactKind);
  }
  if (filters.outcome) {
    params.set('success', filters.outcome);
  }
  const limit = Number.parseInt(filters.limit || '8', 10);
  params.set('limit', Number.isFinite(limit) && limit > 0 ? String(Math.min(limit, 50)) : '8');
  const query = params.toString();
  return query ? `${path}?${query}` : path;
}

async function loadPublicationList(options = {}) {
  try {
    const response = await fetch(visualPublicationSummariesUrl());
    if (!response.ok) {
      throw new Error(`Publication list failed with ${response.status}`);
    }
    state.publicationSummaries = await response.json();
    state.publications = state.publicationSummaries;
    const listedPublicationIds = new Set(state.publications.map((publication) => publication.publicationId));
    for (const publicationId of Object.keys(state.publicationDetailsById)) {
      if (!listedPublicationIds.has(publicationId)) {
        delete state.publicationDetailsById[publicationId];
      }
    }
    if (state.selectedPublicationId
        && !state.publications.some((publication) => publication.publicationId === state.selectedPublicationId)) {
      state.selectedPublicationId = '';
    }
    if (!state.selectedPublicationId && state.publications.length) {
      state.selectedPublicationId = state.publications[0].publicationId;
    }
    await loadSelectedPublicationDetails({ render: false });
    if (options.render !== false) {
      renderPublicationControls();
    }
    return state.publications;
  } catch (error) {
    setPublicationMessage(error.message, 'error');
    return [];
  }
}

async function loadSelectedPublicationDetails(options = {}) {
  if (!state.selectedPublicationId) {
    return null;
  }
  const detail = await loadPublicationDetails(state.selectedPublicationId);
  if (options.render !== false) {
    renderPublicationControls();
  }
  return detail;
}

async function loadPublicationDetails(publicationId) {
  const id = String(publicationId || '').trim();
  if (!id) {
    return null;
  }
  if (state.publicationDetailsById[id]) {
    return state.publicationDetailsById[id];
  }
  const response = await fetch(`/api/visual/publications/${encodeURIComponent(id)}`);
  if (!response.ok) {
    throw new Error(`Publication detail failed with ${response.status}`);
  }
  const publication = await response.json();
  state.publicationDetailsById[id] = publication;
  return publication;
}

async function loadGoldenCases(options = {}) {
  if (!state.selectedPublicationId) {
    state.goldenCases = [];
    state.selectedGoldenCaseId = '';
    state.goldenCertification = null;
    state.goldenCertificationStatus = null;
    if (options.render !== false) {
      renderGoldenCaseControls();
      renderGoldenCertificationStatus();
    }
    return state.goldenCases;
  }
  try {
    const response = await fetch(`/api/visual/golden-cases?publicationId=${encodeURIComponent(state.selectedPublicationId)}`);
    if (!response.ok) {
      throw new Error(`Golden cases failed with ${response.status}`);
    }
    state.goldenCases = await response.json();
    if (state.selectedGoldenCaseId
        && !state.goldenCases.some((testCase) => testCase.caseId === state.selectedGoldenCaseId)) {
      state.selectedGoldenCaseId = '';
    }
    if (!state.selectedGoldenCaseId && state.goldenCases.length) {
      state.selectedGoldenCaseId = state.goldenCases[0].caseId;
    }
    if (options.render !== false) {
      renderGoldenCaseControls();
    }
    return state.goldenCases;
  } catch (error) {
    state.goldenCases = [];
    state.selectedGoldenCaseId = '';
    state.goldenCertificationStatus = null;
    setPublicationMessage(error.message, 'error');
    if (options.render !== false) {
      renderGoldenCaseControls();
    }
    return [];
  }
}

async function loadGoldenCertificationStatus(options = {}) {
  if (!state.selectedPublicationId) {
    state.goldenCertification = null;
    state.goldenCertificationStatus = null;
    if (options.render !== false) {
      renderGoldenCertificationStatus();
    }
    return null;
  }
  try {
    const response = await fetch(
      `/api/visual/golden-cases/publications/${encodeURIComponent(state.selectedPublicationId)}/certification/status`
    );
    if (response.status === 404) {
      state.goldenCertification = null;
      state.goldenCertificationStatus = null;
    } else {
      if (!response.ok) {
        throw new Error(`Golden certification status failed with ${response.status}`);
      }
      state.goldenCertificationStatus = await response.json();
      state.goldenCertification = state.goldenCertificationStatus.certification || null;
    }
  } catch (error) {
    state.goldenCertificationStatus = null;
    state.goldenCertification = null;
    setPublicationMessage(error.message, 'error');
  }
  if (options.render !== false) {
    renderGoldenCertificationStatus();
  }
  return state.goldenCertificationStatus;
}

function selectedPublication() {
  return state.publicationDetailsById[state.selectedPublicationId]
    || state.publications.find((publication) => publication.publicationId === state.selectedPublicationId)
    || null;
}

function selectedGoldenCase() {
  return state.goldenCases.find((testCase) => testCase.caseId === state.selectedGoldenCaseId) || null;
}

async function deleteSelectedGoldenCase() {
  const testCase = selectedGoldenCase();
  if (!testCase) {
    setPublicationMessage('Select a golden case first.', 'error');
    return;
  }
  if (!confirm(`Delete golden case ${testCase.caseId}?`)) return;
  const deletedId = testCase.caseId;
  setPublicationMessage(`Deleting golden ${shortRunId(deletedId)}...`, 'info');
  try {
    const response = await fetch(`/api/visual/golden-cases/${encodeURIComponent(deletedId)}`, {
      method: 'DELETE'
    });
    if (!response.ok) {
      throw new Error(`Delete golden case failed with ${response.status}`);
    }
    if (state.selectedGoldenCaseId === deletedId) {
      state.selectedGoldenCaseId = '';
    }
    await loadGoldenCases({ render: false });
    await loadGoldenCertificationStatus({ render: false });
    $('output').textContent = pretty({ status: response.status, deletedGoldenCase: { caseId: deletedId } });
    setPublicationMessage(`Deleted golden ${shortRunId(deletedId)}.`, 'success');
    renderPublicationControls();
  } catch (error) {
    setPublicationMessage(error.message, 'error');
  }
}

async function saveGoldenCaseFromCurrentOutput() {
  const publication = selectedPublication();
  if (!publication) {
    setPublicationMessage('Select a publication first.', 'error');
    return;
  }
  let context;
  try {
    context = JSON.parse(state.customContextText || '{}');
  } catch (error) {
    setPublicationMessage('Context JSON is invalid.', 'error');
    return;
  }
  if (!context || Array.isArray(context) || typeof context !== 'object') {
    setPublicationMessage('Context JSON must be an object.', 'error');
    return;
  }
  if (!state.lastPayload || !Object.prototype.hasOwnProperty.call(state.lastPayload, 'data')) {
    setPublicationMessage('Run the publication before saving a golden case.', 'error');
    return;
  }
  const graphName = publication.graphName || publication.draft?.graphName || 'visual graph';
  const outputNode = state.lastPayload.composer?.outputNode || '';
  try {
    const assertions = goldenAssertionsFromControls(state.lastPayload.data);
    const response = await fetch('/api/visual/golden-cases', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        publicationId: publication.publicationId,
        name: `${graphName} golden`,
        description: 'Saved from the browser publication output.',
        outputNode,
        context,
        expectedOutput: state.lastPayload.data,
        assertions
      })
    });
    if (!response.ok) {
      throw new Error(`Save golden case failed with ${response.status}`);
    }
    const payload = await response.json();
    state.selectedGoldenCaseId = payload.caseId || '';
    state.goldenAssertions = [];
    setPublicationMessage(`Saved golden ${shortRunId(state.selectedGoldenCaseId)}.`, 'success');
    await loadGoldenCases({ render: false });
    renderGoldenCaseControls();
    await loadGoldenCertificationStatus();
  } catch (error) {
    setPublicationMessage(error.message, 'error');
  }
}

function goldenAssertionsFromControls(actualOutput) {
  const queued = Array.isArray(state.goldenAssertions) ? state.goldenAssertions : [];
  if (queued.length) {
    return queued.map(cloneGoldenAssertion);
  }
  return currentGoldenAssertionsFromControls(actualOutput);
}

function currentGoldenAssertionsFromControls(actualOutput) {
  const mode = state.goldenAssertionMode || 'EXACT_OUTPUT';
  if (mode === 'EXACT_OUTPUT') {
    return [];
  }
  if ((mode === 'PATH_EQUALS' || mode === 'PATH_APPROX_EQUALS'
      || mode === 'PATH_EXISTS' || mode === 'PATH_ABSENT')
      && (!state.goldenAssertionPath || !state.goldenAssertionPath.startsWith('/'))) {
    throw new Error('Golden assertion path must be a JSON Pointer starting with /.');
  }
  if (mode === 'PATH_EXISTS' || mode === 'PATH_ABSENT') {
    return [{ mode, path: state.goldenAssertionPath || '', expectedValue: null }];
  }
  if (mode === 'PATH_APPROX_EQUALS') {
    const expectedValue = state.goldenAssertionValueText && state.goldenAssertionValueText.trim()
      ? JSON.parse(state.goldenAssertionValueText)
      : inferredApproximateAssertionValue(actualOutput, state.goldenAssertionPath);
    return [{ mode, path: state.goldenAssertionPath || '', expectedValue }];
  }
  if (mode === 'OUTPUT_MATCHES_SCHEMA') {
    const expectedValue = state.goldenAssertionValueText && state.goldenAssertionValueText.trim()
      ? JSON.parse(state.goldenAssertionValueText)
      : {
          format: 'json-schema',
          version: '2020-12',
          schema: schemaFromValue(actualOutput)
        };
    return [{ mode, path: '', expectedValue }];
  }
  const expectedValue = state.goldenAssertionValueText && state.goldenAssertionValueText.trim()
    ? JSON.parse(state.goldenAssertionValueText)
    : actualOutput;
  return [{
    mode,
    path: mode === 'PATH_EQUALS' ? state.goldenAssertionPath : '',
    expectedValue
  }];
}

function cloneGoldenAssertion(assertion) {
  return assertion == null ? assertion : JSON.parse(JSON.stringify(assertion));
}

function inferredApproximateAssertionValue(actualOutput, path) {
  const actualValue = valueAtJsonPointer(actualOutput, path);
  if (typeof actualValue !== 'number' || !Number.isFinite(actualValue)) {
    throw new Error('Golden approximate assertion needs a numeric JSON value or explicit expectedValue.');
  }
  return { value: actualValue, tolerance: 0.000001 };
}

function valueAtJsonPointer(value, pointer) {
  if (!pointer) {
    return value;
  }
  if (!String(pointer).startsWith('/')) {
    return undefined;
  }
  return String(pointer)
    .split('/')
    .slice(1)
    .reduce((current, rawSegment) => {
      if (current === undefined || current === null) {
        return undefined;
      }
      const segment = jsonPointerUnescape(rawSegment);
      if (!Object.prototype.hasOwnProperty.call(Object(current), segment)) {
        return undefined;
      }
      return current[segment];
    }, value);
}

async function runSelectedGoldenCase() {
  const testCase = selectedGoldenCase();
  if (!testCase) {
    setPublicationMessage('Select a golden case first.', 'error');
    return;
  }
  setPublicationMessage(`Running golden ${shortRunId(testCase.caseId)}...`, 'info');
  try {
    const response = await fetch(`/api/visual/golden-cases/${encodeURIComponent(testCase.caseId)}/run`, {
      method: 'POST'
    });
    if (!response.ok) {
      throw new Error(`Golden case run failed with ${response.status}`);
    }
    const payload = await response.json();
    const passed = Boolean(payload.passed);
    setPublicationMessage(
      passed ? `Golden ${shortRunId(testCase.caseId)} passed.` : `Golden ${shortRunId(testCase.caseId)} failed.`,
      passed ? 'success' : 'error'
    );
    $('output').textContent = pretty({ status: response.status, goldenCaseRun: payload });
    await loadRunHistory();
  } catch (error) {
    setPublicationMessage(error.message, 'error');
  }
}

